  1→/**
  2→ * Bin Service - Recycle bin metadata IPNS lifecycle
  3→ *
  4→ * Manages the encrypted bin metadata: initialize on login, add entries on delete,
  5→ * restore items, permanent delete (with CID unpin + quota update), empty bin,
  6→ * and auto-purge expired entries.
  7→ *
  8→ * Follows the same IPFS/IPNS patterns as device-registry.service.ts.
  9→ *
 10→ * IMPORTANT: Bin operations must NEVER block login or the delete UI.
 11→ * initializeBin is fire-and-forget; addToBin is fire-and-forget from the
 12→ * delete flow. Errors are caught and logged, not thrown to callers.
 13→ */
 14→
 15→import {
 16→  deriveBinIpnsKeypair,
 17→  encryptBinMetadata,
 18→  decryptBinMetadata,
 19→  bytesToHex,
 20→  hexToBytes,
 21→  wrapKey,
 22→  type RecycleBinMetadata,
 23→  type BinEntry,
 24→  type FolderChild,
 25→  type FilePointer,
 26→  type FolderEntry,
 27→} from '@cipherbox/crypto';
 28→import { addToIpfs, fetchFromIpfs, unpinFromIpfs } from '../lib/api/ipfs';
 29→import { createAndPublishIpnsRecord, resolveIpnsRecord } from './ipns.service';
 30→import { useAuthStore } from '../stores/auth.store';
 31→import { useBinStore } from '../stores/bin.store';
 32→import { useFolderStore } from '../stores/folder.store';
 33→import { useVaultStore } from '../stores/vault.store';
 34→import { useQuotaStore } from '../stores/quota.store';
 35→import type { FolderNode } from '../stores/folder.store';
 36→
 37→// Track whether TEE enrollment has been done for this session
 38→let binTeeEnrolled = false;
 39→
 40→/** Current bin metadata version. */
 41→const BIN_METADATA_VERSION = 'v1' as const;
 42→
 43→// ---------------------------------------------------------------------------
 44→// Internal helpers: load / save bin metadata
 45→// ---------------------------------------------------------------------------
 46→
 47→/**
 48→ * Load and decrypt bin metadata from IPNS.
 49→ *
 50→ * @returns Decrypted metadata and IPNS resolution data, or null if no bin exists yet
 51→ */
 52→async function loadBinMetadata(params: { userPrivateKey: Uint8Array }): Promise<{
 53→  metadata: RecycleBinMetadata;
 54→  ipnsName: string;
 55→  sequenceNumber: bigint;
 56→} | null> {
 57→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 58→  const resolved = await resolveIpnsRecord(binIpns.ipnsName);
 59→
 60→  if (!resolved) {
 61→    return null;
 62→  }
 63→
 64→  const encryptedBytes = await fetchFromIpfs(resolved.cid);
 65→  const metadata = await decryptBinMetadata(encryptedBytes, params.userPrivateKey);
 66→
 67→  return {
 68→    metadata,
 69→    ipnsName: binIpns.ipnsName,
 70→    sequenceNumber: resolved.sequenceNumber,
 71→  };
 72→}
 73→
 74→/**
 75→ * Encrypt and publish bin metadata to IPNS.
 76→ *
 77→ * Handles TEE enrollment on first write.
 78→ */
 79→async function saveBinMetadata(params: {
 80→  metadata: RecycleBinMetadata;
 81→  userPublicKey: Uint8Array;
 82→  userPrivateKey: Uint8Array;
 83→}): Promise<void> {
 84→  const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
 85→
 86→  // Encrypt metadata with user's public key (ECIES)
 87→  const encryptedBytes = await encryptBinMetadata(params.metadata, params.userPublicKey);
 88→
 89→  // Pin to IPFS
 90→  const { cid } = await addToIpfs(new Blob([encryptedBytes as BlobPart]));
 91→
 92→  // TEE enrollment on first write (fire-and-forget)
 93→  let encryptedIpnsKey: string | undefined;
 94→  let keyEpoch: number | undefined;
 95→
 96→  const enrollingTee = !binTeeEnrolled;
 97→  if (enrollingTee) {
 98→    const teeKeys = useAuthStore.getState().teeKeys;
 99→    if (teeKeys?.currentPublicKey) {
100→      try {
101→        const wrappedKey = await wrapKey(binIpns.privateKey, hexToBytes(teeKeys.currentPublicKey));
102→        encryptedIpnsKey = bytesToHex(wrappedKey);
103→        keyEpoch = teeKeys.currentEpoch;
104→      } catch (err) {
105→        console.error('[Bin] TEE enrollment failed (non-blocking):', err);
106→      }
107→    }
108→  }
109→
110→  // Publish IPNS record
111→  await createAndPublishIpnsRecord({
112→    ipnsPrivateKey: binIpns.privateKey,
113→    ipnsName: binIpns.ipnsName,
114→    metadataCid: cid,
115→    sequenceNumber: BigInt(params.metadata.sequenceNumber),
116→    encryptedIpnsPrivateKey: encryptedIpnsKey,
117→    keyEpoch,
118→  });
119→
120→  // Mark TEE enrolled only after successful publish
121→  if (enrollingTee && encryptedIpnsKey) {
122→    binTeeEnrolled = true;
123→  }
124→}
125→
126→// ---------------------------------------------------------------------------
127→// Public API: initializeBin
128→// ---------------------------------------------------------------------------
129→
130→/**
131→ * Initialize or load the recycle bin on login.
132→ *
133→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
134→ * from IPNS (or creates empty state), and populates the bin store.
135→ *
136→ * Non-blocking: errors are logged, not thrown.
137→ */
138→export async function initializeBin(params: {
139→  userPrivateKey: Uint8Array;
140→  userPublicKey: Uint8Array;
141→}): Promise<void> {
142→  const store = useBinStore.getState();
143→  store.setLoading(true);
144→
145→  try {
146→    // Reset TEE enrollment tracking for new session
147→    binTeeEnrolled = false;
148→
149→    // Try to load existing bin metadata (derives IPNS keypair internally)
150→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
151→
152→    // Set IPNS name from loaded result, or derive if no bin exists yet
153→    if (loaded) {
154→      store.setBinIpnsName(loaded.ipnsName);
155→    } else {
156→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
157→      store.setBinIpnsName(binIpns.ipnsName);
158→    }
159→
160→    if (loaded) {
161→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
162→    } else {
163→      // No bin exists yet -- initialize with empty state
164→      store.setEntries([], 0);
165→    }
166→  } catch (error) {
167→    console.error('[Bin] Failed to initialize bin:', error);
168→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
169→    store.setLoading(false);
170→  }
171→}
172→
173→// ---------------------------------------------------------------------------
174→// Public API: addToBin
175→// ---------------------------------------------------------------------------
176→
177→/**
178→ * Add a deleted item to the recycle bin.
179→ *
180→ * Creates a BinEntry from the FolderChild that was removed from its parent,
181→ * appends it to the bin metadata, encrypts, and publishes.
182→ *
183→ * @param params.item - The FolderChild (FilePointer or FolderEntry) that was removed
184→ * @param params.parentIpnsName - IPNS name of the original parent folder
185→ * @param params.parentPath - Breadcrumb path at deletion time (e.g., "My Vault / Documents")
186→ * @param params.userPublicKey - User's secp256k1 public key for ECIES encryption
187→ * @param params.userPrivateKey - User's secp256k1 private key for IPNS derivation
188→ */
189→export async function addToBin(params: {
190→  item: FolderChild;
191→  parentIpnsName: string;
192→  parentPath: string;
193→  userPublicKey: Uint8Array;
194→  userPrivateKey: Uint8Array;
195→}): Promise<void> {
196→  const { item, parentIpnsName, parentPath, userPublicKey, userPrivateKey } = params;
197→
198→  // Build bin entry
199→  const isFile = item.type === 'file';
200→  const entry: BinEntry = {
201→    id: crypto.randomUUID(),
202→    itemType: isFile ? 'file' : 'folder',
203→    name: item.name,
204→    originalParentIpnsName: parentIpnsName,
205→    originalPath: parentPath,
206→    deletedAt: Date.now(),
207→    size: 0, // Files: resolved lazily on permanent delete. Folders: 0.
208→    mimeType: '',
209→    filePointer: isFile ? (item as FilePointer) : undefined,
210→    folderEntry: !isFile ? (item as FolderEntry) : undefined,
211→  };
212→
213→  // Read current bin state and build updated metadata
214→  const store = useBinStore.getState();
215→  const currentEntries = [...store.entries, entry];
216→  const newSeq = store.sequenceNumber + 1;
217→
218→  const metadata: RecycleBinMetadata = {
219→    version: BIN_METADATA_VERSION,
220→    sequenceNumber: newSeq,
221→    entries: currentEntries,
222→  };
223→
224→  // Encrypt and publish (non-blocking: folder delete already committed, bin is best-effort)
225→  try {
226→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
227→    store.setEntries(currentEntries, newSeq);
228→  } catch {
229→    console.error('[Bin] addToBin publish failed (non-blocking)');
230→  }
231→}
232→
233→// ---------------------------------------------------------------------------
234→// Public API: addManyToBin
235→// ---------------------------------------------------------------------------
236→
237→/**
238→ * Add multiple deleted items to the recycle bin in a single IPNS publish.
239→ *
240→ * Unlike calling addToBin in a loop (which publishes per-item), this batches
241→ * all entries into one metadata update.
242→ */
243→export async function addManyToBin(params: {
244→  items: FolderChild[];
245→  parentIpnsName: string;
246→  parentPath: string;
247→  userPublicKey: Uint8Array;
248→  userPrivateKey: Uint8Array;
249→}): Promise<void> {
250→  const { items, parentIpnsName, parentPath, userPublicKey, userPrivateKey } = params;
251→  if (items.length === 0) return;
252→
253→  const now = Date.now();
254→  const newEntries: BinEntry[] = items.map((item) => {
255→    const isFile = item.type === 'file';
256→    return {
257→      id: crypto.randomUUID(),
258→      itemType: isFile ? 'file' : 'folder',
259→      name: item.name,
260→      originalParentIpnsName: parentIpnsName,
261→      originalPath: parentPath,
262→      deletedAt: now,
263→      size: 0,
264→      mimeType: '',
265→      filePointer: isFile ? (item as FilePointer) : undefined,
266→      folderEntry: !isFile ? (item as FolderEntry) : undefined,
267→    };
268→  });
269→
270→  const store = useBinStore.getState();
271→  const currentEntries = [...store.entries, ...newEntries];
272→  const newSeq = store.sequenceNumber + 1;
273→
274→  const metadata: RecycleBinMetadata = {
275→    version: BIN_METADATA_VERSION,
276→    sequenceNumber: newSeq,
277→    entries: currentEntries,
278→  };
279→
280→  // Non-blocking: folder delete already committed, bin is best-effort
281→  try {
282→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
283→    store.setEntries(currentEntries, newSeq);
284→  } catch {
285→    console.error('[Bin] addManyToBin publish failed (non-blocking)');
286→  }
287→}
288→
289→// ---------------------------------------------------------------------------
290→// Public API: restoreFromBin
291→// ---------------------------------------------------------------------------
292→
293→/**
294→ * Restore a bin entry to its original folder.
295→ *
296→ * Looks up the target folder by IPNS name. If found, re-adds the preserved
297→ * FolderChild. Handles name collisions (appends " (restored)"). If original
298→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
299→ * Falls back to root folder if parent is gone.
300→ */
301→export async function restoreFromBin(params: {
302→  entryId: string;
303→  userPublicKey: Uint8Array;
304→  userPrivateKey: Uint8Array;
305→}): Promise<void> {
306→  return restoreFromBinInternal(params, 0);
307→}
308→
309→async function restoreFromBinInternal(
310→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
311→  depth: number
312→): Promise<void> {
313→  const { entryId, userPublicKey, userPrivateKey } = params;
314→
315→  const binStore = useBinStore.getState();
316→  const entry = binStore.entries.find((e) => e.id === entryId);
317→  if (!entry) throw new Error('Bin entry not found');
318→
319→  // Resolve original parent folder
320→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
321→    userPublicKey,
322→    userPrivateKey,
323→  });
324→
325→  // Get the FolderChild to restore
326→  const child = getRestoredChild(entry);
327→
328→  // Check for name collisions in target folder and rename if needed
329→  const finalChild = resolveNameCollision(child, targetFolder.children);
330→
331→  // Add child back to target folder
332→  const { updateFolderMetadata } = await import('./folder.service');
333→  const updatedChildren = [...targetFolder.children, finalChild];
334→  const { newSequenceNumber } = await updateFolderMetadata({
335→    folderId: targetFolder.id,
336→    children: updatedChildren,
337→    folderKey: targetFolder.folderKey,
338→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
339→    ipnsName: targetFolder.ipnsName,
340→    sequenceNumber: targetFolder.sequenceNumber,
341→  });
342→
343→  // Update folder store
344→  const folderStore = useFolderStore.getState();
345→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
346→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
347→
348→  // If restoring a folder, re-add the folder node to the store
349→  if (entry.itemType === 'folder' && entry.folderEntry) {
350→    const existingNode = folderStore.folders[entry.folderEntry.id];
351→    if (!existingNode) {
352→      // Create a placeholder node -- it will be fully loaded on next navigation
353→      folderStore.setFolder({
354→        id: entry.folderEntry.id,
355→        name: finalChild.name,
356→        ipnsName: entry.folderEntry.ipnsName,
357→        parentId: targetFolder.id,
358→        children: [],
359→        isLoaded: false,
360→        isLoading: false,
361→        sequenceNumber: 0n,
362→        // These will be populated when the folder is loaded
363→        folderKey: new Uint8Array(32),
364→        ipnsPrivateKey: new Uint8Array(64),
365→      });
366→    }
367→  }
368→
369→  // Remove entry from bin metadata and publish
370→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
371→}
372→
373→// ---------------------------------------------------------------------------
374→// Public API: restoreFromBinBatch
375→// ---------------------------------------------------------------------------
376→
377→/**
378→ * Restore multiple bin entries, publishing to the bin IPNS only once at the end.
379→ *
380→ * Each item is restored to its target folder (which may each require a folder
381→ * publish), but the bin metadata is updated in a single publish.
382→ */
383→export async function restoreFromBinBatch(params: {
384→  entryIds: string[];
385→  userPublicKey: Uint8Array;
386→  userPrivateKey: Uint8Array;
387→}): Promise<void> {
388→  const { entryIds, userPublicKey, userPrivateKey } = params;
389→  if (entryIds.length === 0) return;
390→
391→  const { updateFolderMetadata } = await import('./folder.service');
392→
393→  const restoredIds: string[] = [];
394→
395→  for (const entryId of entryIds) {
396→    // Read fresh state each iteration — recursive restores may mutate the store
397→    const entry = useBinStore.getState().entries.find((e) => e.id === entryId);
398→    if (!entry) continue;
399→
400→    try {
401→      const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, 0, {
402→        userPublicKey,
403→        userPrivateKey,
404→      });
405→
406→      const child = getRestoredChild(entry);
407→      const finalChild = resolveNameCollision(child, targetFolder.children);
408→
409→      const updatedChildren = [...targetFolder.children, finalChild];
410→      const { newSequenceNumber } = await updateFolderMetadata({
411→        folderId: targetFolder.id,
412→        children: updatedChildren,
413→        folderKey: targetFolder.folderKey,
414→        ipnsPrivateKey: targetFolder.ipnsPrivateKey,
415→        ipnsName: targetFolder.ipnsName,
416→        sequenceNumber: targetFolder.sequenceNumber,
417→      });
418→
419→      const folderStore = useFolderStore.getState();
420→      folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
421→      folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
422→
423→      if (entry.itemType === 'folder' && entry.folderEntry) {
424→        const existingNode = folderStore.folders[entry.folderEntry.id];
425→        if (!existingNode) {
426→          folderStore.setFolder({
427→            id: entry.folderEntry.id,
428→            name: finalChild.name,
429→            ipnsName: entry.folderEntry.ipnsName,
430→            parentId: targetFolder.id,
431→            children: [],
432→            isLoaded: false,
433→            isLoading: false,
434→            sequenceNumber: 0n,
435→            folderKey: new Uint8Array(32),
436→            ipnsPrivateKey: new Uint8Array(64),
437→          });
438→        }
439→      }
440→
441→      restoredIds.push(entryId);
442→    } catch (err) {
443→      console.error(`[Bin] Failed to restore entry ${entry.id}:`, err);
444→    }
445→  }
446→
447→  // Single bin IPNS publish for all restored entries
448→  if (restoredIds.length > 0) {
449→    await removeEntriesFromBin(restoredIds, { userPublicKey, userPrivateKey });
450→  }
451→}
452→
453→// ---------------------------------------------------------------------------
454→// Public API: permanentlyDelete
455→// ---------------------------------------------------------------------------
456→
457→/**
458→ * Permanently delete a bin entry: unpin CIDs and update quota.
459→ *
460→ * For files: resolves file IPNS -> gets CID -> unpins.
461→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
462→ */
463→export async function permanentlyDelete(params: {
464→  entryId: string;
465→  userPublicKey: Uint8Array;
466→  userPrivateKey: Uint8Array;
467→}): Promise<void> {
468→  const { entryId, userPublicKey, userPrivateKey } = params;
469→
470→  const binStore = useBinStore.getState();
471→  const entry = binStore.entries.find((e) => e.id === entryId);
472→  if (!entry) throw new Error('Bin entry not found');
473→
474→  // Perform CID cleanup
475→  await cleanupEntryCids(entry);
476→
477→  // Remove from bin metadata and publish
478→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
479→}
