485→/**
486→ * Permanently delete multiple bin entries in a single IPNS publish.
487→ *
488→ * Cleans up CIDs for all entries (best-effort), then publishes once.
489→ */
490→export async function permanentlyDeleteBatch(params: {
491→  entryIds: string[];
492→  userPublicKey: Uint8Array;
493→  userPrivateKey: Uint8Array;
494→}): Promise<void> {
495→  const { entryIds, userPublicKey, userPrivateKey } = params;
496→  if (entryIds.length === 0) return;
497→
498→  const binStore = useBinStore.getState();
499→  const idsSet = new Set(entryIds);
500→  const entriesToDelete = binStore.entries.filter((e) => idsSet.has(e.id));
501→
502→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
503→  for (const entry of entriesToDelete) {
504→    try {
505→      await cleanupEntryCids(entry);
506→    } catch (err) {
507→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
508→    }
509→  }
510→
511→  // Remove all from bin metadata in a single publish
512→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
513→}
