519→/**
520→ * Permanently delete all bin entries.
521→ *
522→ * Processes each entry's CID cleanup, then publishes empty bin metadata.
523→ */
524→export async function emptyBin(params: {
525→  userPublicKey: Uint8Array;
526→  userPrivateKey: Uint8Array;
527→}): Promise<void> {
528→  const { userPublicKey, userPrivateKey } = params;
529→
530→  const binStore = useBinStore.getState();
531→  const entries = [...binStore.entries];
532→
533→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
534→  for (const entry of entries) {
