600→/**
601→ * Remove entries from bin metadata and publish the updated metadata.
602→ */
603→async function removeEntriesFromBin(
604→  entryIds: string[],
605→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
606→): Promise<void> {
607→  const binStore = useBinStore.getState();
608→  const idsToRemove = new Set(entryIds);
609→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
610→  const newSeq = binStore.sequenceNumber + 1;
611→
612→  const metadata: RecycleBinMetadata = {
613→    version: BIN_METADATA_VERSION,
614→    sequenceNumber: newSeq,
615→    entries: remainingEntries,
616→  };
617→
618→  await saveBinMetadata({
619→    metadata,
620→    userPublicKey: params.userPublicKey,
621→    userPrivateKey: params.userPrivateKey,
622→  });
623→
624→  // Update local store (use setEntries with explicit seq to avoid double-increment)
625→  binStore.setEntries(remainingEntries, newSeq);
626→}
