628→/**
629→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
630→ *
631→ * Files: resolve file IPNS -> get CID -> unpin
632→ * Folders: recursively resolve descendant file CIDs -> unpin all
633→ */
634→async function cleanupEntryCids(entry: BinEntry): Promise<void> {
635→  if (entry.itemType === 'file' && entry.filePointer) {
636→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
637→    if (fileIpnsName) {
638→      await unpinFileCids(fileIpnsName, `file ${entry.id}`);
639→    }
640→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
641→    await cleanupFolderCids(entry.folderEntry.ipnsName);
642→  }
643→}
644→
645→/**
646→ * Unpin a single file's content and metadata CIDs, and update quota.
647→ */
648→async function unpinFileCids(fileMetaIpnsName: string, label: string): Promise<void> {
649→  try {
650→    const resolved = await resolveIpnsRecord(fileMetaIpnsName);
651→    if (!resolved?.cid) return;
652→
653→    const metaBytes = await fetchFromIpfs(resolved.cid);
654→    const metaJson = new TextDecoder().decode(metaBytes);
655→    const fileMeta = JSON.parse(metaJson);
656→
657→    if (fileMeta.cid) {
658→      await unpinFromIpfs(fileMeta.cid);
659→      if (fileMeta.size && typeof fileMeta.size === 'number') {
660→        useQuotaStore.getState().removeUsage(fileMeta.size);
661→      }
662→    }
663→
664→    await unpinFromIpfs(resolved.cid).catch(() => {});
665→  } catch (err) {
666→    console.error(`[Bin] CID cleanup failed for ${label}:`, err);
667→  }
668→}
669→
670→/**
671→ * Recursively unpin all CIDs in a folder tree.
672→ */
673→async function cleanupFolderCids(folderIpnsName: string): Promise<void> {
674→  try {
675→    const resolved = await resolveIpnsRecord(folderIpnsName);
676→    if (!resolved?.cid) return;
677→
678→    // We don't have the folder key here, so we check if the folder is
679→    // loaded in the store first
680→    const folders = useFolderStore.getState().folders;
681→    const folderNode = Object.values(folders).find((f) => f.ipnsName === folderIpnsName);
682→
683→    if (folderNode) {
684→      for (const child of folderNode.children) {
685→        if (child.type === 'file') {
686→          const fp = child as FilePointer;
687→          if (fp.fileMetaIpnsName) {
688→            await unpinFileCids(fp.fileMetaIpnsName, 'nested file');
689→          }
690→        } else if (child.type === 'folder') {
691→          const fe = child as FolderEntry;
692→          await cleanupFolderCids(fe.ipnsName);
693→        }
694→      }
695→    }
696→
697→    await unpinFromIpfs(resolved.cid).catch(() => {});
698→  } catch (err) {
699→    console.error(`[Bin] Folder CID cleanup failed for ${folderIpnsName}:`, err);
700→  }
701→}
