703→/**
704→ * Resolve the target folder for a restore operation.
705→ *
706→ * Walks the folder store to find a folder with the given IPNS name.
707→ * If not found, checks if the parent is in the bin (recursive restore).
708→ * Falls back to root folder.
709→ */
710→async function resolveTargetFolder(
711→  parentIpnsName: string,
712→  depth: number,
713→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
714→): Promise<FolderNode> {
715→  // Max recursion depth to prevent infinite loops
716→  if (depth > 5) {
717→    console.warn('[Bin] Max restore depth reached, falling back to root');
718→    return getRootFolder();
719→  }
720→
721→  // Look up folder by IPNS name in folder store
722→  const folders = useFolderStore.getState().folders;
723→  const targetFolder = Object.values(folders).find((f) => f.ipnsName === parentIpnsName);
724→
725→  if (targetFolder) {
726→    return targetFolder;
727→  }
728→
729→  // Check if parent is in the bin
730→  const binStore = useBinStore.getState();
731→  const parentBinEntry = binStore.entries.find(
732→    (e) => e.itemType === 'folder' && e.folderEntry && e.folderEntry.ipnsName === parentIpnsName
733→  );
734→
735→  if (parentBinEntry) {
736→    // Restore parent first (recursive, depth incremented)
737→    console.log(`[Bin] Restoring parent folder (id: ${parentBinEntry.id}) first`);
738→    await restoreFromBinInternal(
739→      {
740→        entryId: parentBinEntry.id,
741→        userPublicKey: params.userPublicKey,
742→        userPrivateKey: params.userPrivateKey,
743→      },
744→      depth + 1
745→    );
746→
747→    // After restoring parent, try to find it again
748→    const updatedFolders = useFolderStore.getState().folders;
749→    const restoredParent = Object.values(updatedFolders).find((f) => f.ipnsName === parentIpnsName);
750→    if (restoredParent) {
751→      return restoredParent;
752→    }
753→  }
754→
755→  // Parent truly gone -- restore to root
756→  console.warn(`[Bin] Original parent not found (${parentIpnsName}), restoring to root`);
757→  return getRootFolder();
758→}
759→
760→/**
761→ * Get the root folder from the folder store.
762→ */
763→function getRootFolder(): FolderNode {
764→  const folders = useFolderStore.getState().folders;
765→  const root = folders['root'];
766→  if (root) return root;
767→
768→  // Fallback: construct from vault store
769→  const vault = useVaultStore.getState();
770→  if (!vault.rootFolderKey || !vault.rootIpnsKeypair || !vault.rootIpnsName) {
771→    throw new Error('Vault not initialized - cannot restore to root');
772→  }
773→
774→  return {
775→    id: 'root',
776→    name: 'My Vault',
777→    ipnsName: vault.rootIpnsName,
778→    parentId: null,
779→    children: folders['root']?.children ?? [],
780→    isLoaded: true,
781→    isLoading: false,
782→    sequenceNumber: 0n,
783→    folderKey: vault.rootFolderKey,
784→    ipnsPrivateKey: vault.rootIpnsKeypair.privateKey,
785→  };
786→}
787→
788→/**
789→ * Get the FolderChild to restore from a bin entry.
790→ */
791→function getRestoredChild(entry: BinEntry): FolderChild {
792→  if (entry.itemType === 'file' && entry.filePointer) {
793→    return { ...entry.filePointer, modifiedAt: Date.now() };
794→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
795→    return { ...entry.folderEntry, modifiedAt: Date.now() };
796→  }
797→  throw new Error(`Bin entry ${entry.id} has no stored item reference`);
798→}
799→
800→/**
801→ * Check for name collisions and rename if needed.
802→ */
803→function resolveNameCollision(child: FolderChild, existingChildren: FolderChild[]): FolderChild {
804→  const existingNames = new Set(existingChildren.map((c) => c.name));
805→  if (!existingNames.has(child.name)) {
806→    return child;
807→  }
808→
809→  // Append " (restored)" suffix, incrementing if needed
810→  let newName = `${child.name} (restored)`;
811→  let counter = 2;
812→  while (existingNames.has(newName)) {
813→    newName = `${child.name} (restored ${counter})`;
814→    counter++;
815→  }
816→
817→  return { ...child, name: newName };
818→}
