 19→/**
 20→ * Build a breadcrumb-style path string for a folder by walking up the tree.
 21→ * e.g., "My Vault / Documents / Reports"
 22→ */
 23→function buildFolderPath(folderId: string): string {
 24→  const folders = useFolderStore.getState().folders;
 25→  const parts: string[] = [];
 26→  let currentId: string | null = folderId;
 27→
 28→  while (currentId !== null) {
 29→    const folder: FolderNode | undefined = folders[currentId];
 30→    if (!folder) break;
 31→    // Stop before including the root node (its name is already the "My Vault" prefix)
 32→    if (folder.parentId === null) break;
 33→    parts.unshift(folder.name);
 34→    currentId = folder.parentId;
 35→  }
 36→
 37→  return parts.length > 0 ? `My Vault / ${parts.join(' / ')}` : 'My Vault';
 38→}
