 40→/**
 41→ * React hook for folder CRUD operations (create, rename, move, delete).
 42→ *
 43→ * Returns loading/error state and operation callbacks.
 44→ */
 45→export function useFolderMutations() {
 46→  const [state, setState] = useState<FolderOperationState>({
 47→    isLoading: false,
 48→    error: null,
 49→  });
 50→
 51→  /**
 52→   * Create a new folder.
 53→   *
 54→   * @param name - Folder name
 55→   * @param parentId - Parent folder ID (null for root, or folder UUID)
 56→   * @returns Created folder entry
 57→   * @throws Error if depth limit exceeded or creation fails
 58→   */
 59→  const handleCreate = useCallback(
 60→    async (name: string, parentId: string | null): Promise<FolderEntry> => {
 61→      setState({ isLoading: true, error: null });
 62→      try {
 63→        const folders = useFolderStore.getState().folders;
 64→        const vault = useVaultStore.getState();
 65→        const auth = useAuthStore.getState();
 66→
 67→        // Validate depth limit before creating (FOLD-03)
 68→        const parentDepth = folderService.getDepth(parentId, folders);
 69→        if (parentDepth >= MAX_FOLDER_DEPTH) {
 70→          throw new Error(`Cannot create folder: maximum depth of ${MAX_FOLDER_DEPTH} exceeded`);
 71→        }
 72→
 73→        // Get user's ECIES keypair for vault cryptographic operations (public + private keys stored in memory after login)
 74→        // The public key is used here for key wrapping; the private key remains client-side for decryption operations.
 75→        if (!auth.vaultKeypair) {
 76→          throw new Error('No ECIES keypair available - please log in again');
 77→        }
 78→        const userPublicKey = auth.vaultKeypair.publicKey;
 79→
 80→        // Create the folder (generates keys, wraps with user public key, TEE-encrypts IPNS key)
 81→        const { folder, ipnsPrivateKey, folderKey, encryptedIpnsPrivateKey, keyEpoch } =
 82→          await folderService.createFolder({
 83→            parentFolderId: parentId,
 84→            name,
 85→            userPublicKey,
 86→            folders,
 87→          });
 88→
 89→        // Get parent folder state
 90→        const parentFolder =
 91→          parentId && folders[parentId] ? folders[parentId] : getRootFolderState(vault, folders);
 92→
 93→        if (!parentFolder) {
 94→          throw new Error('Parent folder not found or vault not initialized');
 95→        }
 96→
 97→        // Update parent folder metadata and publish IPNS (with conflict retry)
 98→        const performParentUpdate = async () => {
 99→          const freshState = useFolderStore.getState();
100→          const freshParent =
101→            parentId && freshState.folders[parentId]
102→              ? freshState.folders[parentId]
103→              : getRootFolderState(useVaultStore.getState(), freshState.folders);
104→          if (!freshParent) throw new Error('Parent folder not found');
105→          const freshChildren = [...freshParent.children, folder];
106→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
107→            folderId: freshParent.id,
108→            children: freshChildren,
109→            folderKey: freshParent.folderKey,
110→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
111→            ipnsName: freshParent.ipnsName,
112→            sequenceNumber: freshParent.sequenceNumber,
113→          });
114→          return { children: freshChildren, newSequenceNumber };
115→        };
116→
117→        const parentResult = await withConflictRetry(performParentUpdate, () =>
118→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
119→        );
120→
121→        // First publish for the new folder's own IPNS record with TEE-encrypted key
122→        // This sends encryptedIpnsPrivateKey to backend for TEE republish enrollment
123→        const { newSequenceNumber: newFolderSequence } = await folderService.updateFolderMetadata({
124→          folderId: folder.id,
125→          children: [],
126→          folderKey,
127→          ipnsPrivateKey,
128→          ipnsName: folder.ipnsName,
129→          sequenceNumber: 0n,
130→          encryptedIpnsPrivateKey,
131→          keyEpoch,
132→        });
133→
134→        // Update local state - add new folder to tree and persist sequence
135→        useFolderStore.getState().updateFolderChildren(parentFolder.id, parentResult.children);
136→        useFolderStore
137→          .getState()
138→          .updateFolderSequence(parentFolder.id, parentResult.newSequenceNumber);
139→
140→        // Also add the new folder node to the store (with its decrypted keys)
141→        const newFolderNode: FolderNode = {
142→          id: folder.id,
143→          name: folder.name,
144→          ipnsName: folder.ipnsName,
145→          parentId: parentFolder.id,
146→          children: [],
147→          isLoaded: true,
148→          isLoading: false,
149→          sequenceNumber: newFolderSequence,
150→          folderKey,
151→          ipnsPrivateKey,
152→        };
153→        useFolderStore.getState().setFolder(newFolderNode);
154→
155→        // Post-create: re-wrap new subfolder key for share recipients (fire-and-forget)
156→        reWrapForRecipients({
157→          folderIpnsName: parentFolder.ipnsName,
158→          folders: useFolderStore.getState().folders,
159→          currentFolderId: parentFolder.id,
160→          newItems: [{ keyType: 'folder', itemId: folder.id, plaintextKey: folderKey }],
161→        })
162→          .then(({ failedRecipients }) => {
163→            if (failedRecipients.length > 0) {
164→              useNotificationStore
165→                .getState()
166→                .addNotification(
167→                  'warning',
168→                  `Failed to update share keys for ${failedRecipients.length} recipient(s). They may not be able to access the new folder until you re-share.`
169→                );
170→            }
171→          })
172→          .catch((err) => {
173→            console.warn('[share] Post-create subfolder re-wrapping failed:', err);
174→          });
175→
176→        setState({ isLoading: false, error: null });
177→        return folder;
178→      } catch (err) {
179→        const error = err instanceof Error ? err.message : 'Failed to create folder';
180→        setState({ isLoading: false, error });
181→        throw err;
182→      }
183→    },
184→    []
185→  );
