297→        const sourceFolder = getSourceFolder();
298→        const destFolder = getDestFolder();
299→        if (!sourceFolder || !destFolder) {
300→          throw new Error('Source or destination folder not found');
301→        }
302→
303→        const performMove = async (): Promise<{
304→          destSequenceNumber: bigint;
305→          sourceSequenceNumber: bigint;
306→        }> => {
307→          const freshSource = getSourceFolder();
308→          const freshDest = getDestFolder();
309→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
310→          const folders = useFolderStore.getState().folders;
311→          if (itemType === 'folder') {
312→            return await folderService.moveFolder({
313→              folderId: itemId,
314→              sourceFolderState: freshSource,
315→              destFolderState: freshDest,
316→              folders,
317→            });
318→          } else {
319→            return await folderService.moveFile({
320→              fileId: itemId,
321→              sourceFolderState: freshSource,
322→              destFolderState: freshDest,
323→            });
324→          }
325→        };
326→
327→        const moveResult = await withConflictRetry(performMove, async () => {
328→          await Promise.all([
329→            resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
330→            sourceFolder.id !== destFolder.id
331→              ? resyncFolder(destFolder.ipnsName, destFolder.id)
332→              : Promise.resolve(),
333→          ]);
334→        });
335→
336→        // Save the moved item BEFORE updating source children (otherwise it's already gone)
337→        const freshSourceBeforeUpdate = getSourceFolder();
338→        const movedItem = freshSourceBeforeUpdate?.children.find((c) => c.id === itemId);
339→
340→        if (itemType === 'folder') {
341→          // Update the moved folder's parentId in local state
342→          const freshFolders = useFolderStore.getState().folders;
343→          const movedFolder = freshFolders[itemId];
344→          if (movedFolder) {
345→            useFolderStore.getState().setFolder({
346→              ...movedFolder,
347→              parentId: destParentId,
348→            });
349→          }
350→        }
351→
352→        // Update source folder's children (remove item)
353→        if (freshSourceBeforeUpdate) {
354→          const updatedSourceChildren = freshSourceBeforeUpdate.children.filter(
355→            (c) => c.id !== itemId
356→          );
357→          useFolderStore.getState().updateFolderChildren(sourceParentId, updatedSourceChildren);
358→        }
359→
360→        // Update dest folder's children (add item)
361→        const freshDest = getDestFolder();
362→        if (movedItem && freshDest) {
363→          const updatedDestChildren = [
364→            ...freshDest.children,
365→            { ...movedItem, modifiedAt: Date.now() },
366→          ];
367→          useFolderStore.getState().updateFolderChildren(destParentId, updatedDestChildren);
368→        }
369→
370→        // Persist the new sequence numbers so subsequent operations use the correct values
371→        useFolderStore.getState().updateFolderSequence(destParentId, moveResult.destSequenceNumber);
372→        useFolderStore
373→          .getState()
374→          .updateFolderSequence(sourceParentId, moveResult.sourceSequenceNumber);
375→
376→        setState({ isLoading: false, error: null });
377→      } catch (err) {
378→        const error = err instanceof Error ? err.message : 'Failed to move';
379→        setState({ isLoading: false, error });
380→        throw err;
381→      }
382→    },
383→    []
384→  );
385→
386→  /**
387→   * Move multiple files/folders to a destination in a single batch.
388→   *
389→   * Uses add-before-remove pattern. Publishes IPNS once for the destination
390→   * and once for the source (2 total), regardless of how many items are moved.
391→   *
392→   * @param items - Array of { id, type } to move
393→   * @param sourceParentId - Current parent folder ID (all items must share the same parent)
394→   * @param destParentId - Destination parent folder ID
395→   */
396→  const handleMoveItems = useCallback(
397→    async (
398→      items: Array<{ id: string; type: 'file' | 'folder' }>,
399→      sourceParentId: string,
400→      destParentId: string
401→    ): Promise<void> => {
402→      setState({ isLoading: true, error: null });
403→      try {
404→        const getSourceFolder = () => {
405→          const freshState = useFolderStore.getState();
406→          return sourceParentId === 'root'
407→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
408→            : freshState.folders[sourceParentId];
409→        };
410→        const getDestFolder = () => {
411→          const freshState = useFolderStore.getState();
412→          return destParentId === 'root'
413→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
414→            : freshState.folders[destParentId];
415→        };
416→
417→        const sourceFolder = getSourceFolder();
418→        const destFolder = getDestFolder();
419→
420→        if (!sourceFolder || !destFolder) {
421→          throw new Error('Source or destination folder not found');
422→        }
423→
424→        const itemIds = new Set(items.map((i) => i.id));
425→        const now = Date.now();
426→
427→        // Validate batch move preconditions against current folder state.
428→        // Must be called before each attempt (initial + retry after resync)
429→        // because concurrent changes may introduce name collisions or depth violations.
430→        const validateBatchMove = () => {
431→          const currentSource = getSourceFolder();
432→          const currentDest = getDestFolder();
433→          if (!currentSource || !currentDest) {
434→            throw new Error('Source or destination folder not found');
435→          }
436→
437→          const currentMovedChildren = currentSource.children.filter((c) => itemIds.has(c.id));
438→          if (currentMovedChildren.length !== itemIds.size) {
439→            throw new Error(
440→              'One or more selected items no longer exist. Please refresh and retry.'
441→            );
442→          }
443→          const batchNames = new Set<string>();
444→          for (const child of currentMovedChildren) {
445→            // Intra-batch duplicate name check
446→            if (batchNames.has(child.name)) {
447→              throw new Error(`Multiple selected items share the name "${child.name}"`);
448→            }
449→            batchNames.add(child.name);
450→
451→            // Name collision check against destination
452→            const nameExists = currentDest.children.some((c) => c.name === child.name);
453→            if (nameExists) {
454→              throw new Error(`An item named "${child.name}" already exists in the destination`);
455→            }
456→
457→            if (child.type === 'folder') {
458→              // Prevent moving folder into itself or descendant
459→              const folders = useFolderStore.getState().folders;
460→              if (folderService.isDescendantOf(currentDest.id, child.id, folders)) {
461→                throw new Error(`Cannot move "${child.name}" into itself or its subfolder`);
462→              }
463→
464→              // Depth limit check
465→              const destDepth = folderService.getDepth(currentDest.id, folders);
466→              const subtreeDepth = folderService.calculateSubtreeDepth(child.id, folders);
467→              if (destDepth + 1 + subtreeDepth > MAX_FOLDER_DEPTH) {
468→                throw new Error(
469→                  `Cannot move "${child.name}": would exceed maximum folder depth of ${MAX_FOLDER_DEPTH}`
470→                );
471→              }
472→            }
473→          }
474→        };
475→
476→        validateBatchMove();
477→
478→        const performBatchMove = async (): Promise<{
479→          destSeq: bigint;
480→          sourceSeq: bigint;
481→          destChildren: FolderNode['children'];
482→          sourceChildren: FolderNode['children'];
483→        }> => {
484→          const freshSource = getSourceFolder();
485→          const freshDest = getDestFolder();
486→          if (!freshSource || !freshDest) throw new Error('Source or destination folder not found');
487→
488→          // Rebuild moved children from fresh source state
489→          const freshMoved = freshSource.children.filter((c) => itemIds.has(c.id));
490→          if (freshMoved.length !== itemIds.size) {
491→            throw new Error(
492→              'One or more selected items no longer exist. Please refresh and retry.'
493→            );
494→          }
495→
496→          // ADD all to destination FIRST (add-before-remove pattern)
497→          const destChildren = [
498→            ...freshDest.children,
499→            ...freshMoved.map((c) => ({ ...c, modifiedAt: now })),
500→          ];
501→
502→          const { newSequenceNumber: destSeq } = await folderService.updateFolderMetadata({
503→            folderId: freshDest.id,
504→            children: destChildren,
505→            folderKey: freshDest.folderKey,
506→            ipnsPrivateKey: freshDest.ipnsPrivateKey,
507→            ipnsName: freshDest.ipnsName,
508→            sequenceNumber: freshDest.sequenceNumber,
509→          });
510→
511→          // REMOVE all from source AFTER destination confirmed
512→          const sourceChildren = freshSource.children.filter((c) => !itemIds.has(c.id));
513→
514→          const { newSequenceNumber: sourceSeq } = await folderService.updateFolderMetadata({
515→            folderId: freshSource.id,
516→            children: sourceChildren,
517→            folderKey: freshSource.folderKey,
518→            ipnsPrivateKey: freshSource.ipnsPrivateKey,
519→            ipnsName: freshSource.ipnsName,
520→            // Re-read sequence in case source === dest parent was updated above
521→            sequenceNumber: freshSource.id === freshDest.id ? destSeq : freshSource.sequenceNumber,
522→          });
523→
524→          return { destSeq, sourceSeq, destChildren, sourceChildren };
525→        };
526→
527→        const result = await withConflictRetry(
528→          performBatchMove,
529→          async () => {
530→            await Promise.all([
531→              resyncFolder(sourceFolder.ipnsName, sourceFolder.id),
532→              sourceFolder.id !== destFolder.id
533→                ? resyncFolder(destFolder.ipnsName, destFolder.id)
534→                : Promise.resolve(),
535→            ]);
536→          },
537→          validateBatchMove
538→        );
539→
540→        // Update local state
541→        const store = useFolderStore.getState();
542→        store.updateFolderChildren(sourceParentId, result.sourceChildren);
543→        store.updateFolderChildren(destParentId, result.destChildren);
544→        store.updateFolderSequence(destParentId, result.destSeq);
545→        store.updateFolderSequence(sourceParentId, result.sourceSeq);
546→
547→        for (const item of items) {
548→          if (item.type === 'folder') {
549→            const movedFolder = useFolderStore.getState().folders[item.id];
550→            if (movedFolder) {
551→              store.setFolder({ ...movedFolder, parentId: destParentId });
552→            }
553→          }
554→        }
555→
556→        setState({ isLoading: false, error: null });
557→      } catch (err) {
558→        const error = err instanceof Error ? err.message : 'Failed to move items';
559→        setState({ isLoading: false, error });
560→        throw err;
561→      }
562→    },
563→    []
564→  );
565→
566→  /**
567→   * Delete a file or folder.
568→   *
569→   * @param itemId - ID of item to delete
570→   * @param itemType - 'file' or 'folder'
571→   * @param parentId - Parent folder ID
572→   */
573→  const handleDelete = useCallback(
574→    async (itemId: string, itemType: 'file' | 'folder', parentId: string): Promise<void> => {
575→      setState({ isLoading: true, error: null });
576→      try {
577→        const getParentFolder = () => {
578→          const freshState = useFolderStore.getState();
579→          return parentId === 'root'
580→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
581→            : freshState.folders[parentId];
582→        };
583→
584→        const parentFolder = getParentFolder();
585→        if (!parentFolder) throw new Error('Parent folder not found');
586→
587→        const performDelete = async (): Promise<{
588→          newSequenceNumber: bigint;
589→          removedChild: FolderChild;
590→        }> => {
591→          const freshParent = getParentFolder();
592→          if (!freshParent) throw new Error('Parent folder not found');
593→          if (itemType === 'folder') {
594→            const folders = useFolderStore.getState().folders;
595→            const { newSequenceNumber, removedChild } = await folderService.deleteFolder({
596→              folderId: itemId,
597→              parentFolderState: freshParent,
598→              getFolderState: (id) => folders[id],
599→            });
600→            return { newSequenceNumber, removedChild };
601→          } else {
602→            const { newSequenceNumber, removedChild } = await folderService.deleteFileFromFolder({
603→              fileId: itemId,
604→              parentFolderState: freshParent,
605→            });
606→            return { newSequenceNumber, removedChild };
607→          }
608→        };
609→
610→        const deleteResult = await withConflictRetry(performDelete, () =>
611→          resyncFolder(parentFolder.ipnsName, parentFolder.id)
612→        );
613→
614→        if (itemType === 'folder') {
615→          // Remove folder and all loaded descendants from local state
616→          const store = useFolderStore.getState();
617→          const removeRecursive = (folderId: string) => {
618→            const node = store.folders[folderId];
619→            if (node) {
620→              for (const child of node.children) {
621→                if (child.type === 'folder') removeRecursive(child.id);
622→              }
623→            }
624→            store.removeFolder(folderId);
625→          };
626→          removeRecursive(itemId);
627→        }
628→
629→        // Update parent's children (remove item) using fresh state
630→        const freshParent = getParentFolder();
631→        if (freshParent) {
632→          const updatedChildren = freshParent.children.filter((c) => c.id !== itemId);
633→          useFolderStore.getState().updateFolderChildren(parentId, updatedChildren);
634→        }
635→
636→        // Persist the new sequence number so subsequent operations use the correct value
637→        useFolderStore.getState().updateFolderSequence(parentId, deleteResult.newSequenceNumber);
638→
639→        // Fire-and-forget: add deleted item to recycle bin (CIDs stay pinned for recovery)
640→        const auth = useAuthStore.getState();
641→        if (auth.vaultKeypair) {
642→          void addManyToBin({
643→            items: [deleteResult.removedChild],
644→            parentIpnsName: parentFolder.ipnsName,
645→            parentPath: buildFolderPath(parentId),
646→            userPublicKey: auth.vaultKeypair.publicKey,
647→            userPrivateKey: auth.vaultKeypair.privateKey,
648→          }).catch(() => {
649→            console.error('[Delete] Failed to add to bin (non-blocking)');
650→          });
651→        }
652→
653→        setState({ isLoading: false, error: null });
654→      } catch (err) {
655→        const error = err instanceof Error ? err.message : 'Failed to delete';
656→        setState({ isLoading: false, error });
657→        throw err;
658→      }
659→    },
660→    []
661→  );
662→
663→  /**
664→   * Delete multiple files/folders in a single IPNS publish.
665→   *
666→   * Removes all items from parent's children array, collects CIDs to unpin,
667→   * then publishes metadata and IPNS once for the entire batch.
668→   *
669→   * @param items - Array of { id, type } to delete
670→   * @param parentId - Parent folder ID (all items must share the same parent)
671→   */
672→  const handleDeleteItems = useCallback(
673→    async (
674→      items: Array<{ id: string; type: 'file' | 'folder' }>,
675→      parentId: string
676→    ): Promise<void> => {
677→      setState({ isLoading: true, error: null });
678→      try {
679→        const getParentFolder = () => {
680→          const freshState = useFolderStore.getState();
681→          return parentId === 'root'
682→            ? getRootFolderState(useVaultStore.getState(), freshState.folders)
683→            : freshState.folders[parentId];
684→        };
685→
686→        const parentFolder = getParentFolder();
687→        if (!parentFolder) throw new Error('Parent folder not found');
688→
689→        const itemIds = new Set(items.map((i) => i.id));
690→
691→        // Collect nested folder IDs to remove from store
692→        // In v2, file children are FilePointers (no inline CID). File IPNS/TEE
693→        // enrollments will expire naturally (24h IPNS lifetime). Phase 14 adds cleanup.
694→        const folderIdsToRemove: string[] = [];
695→
696→        const collectFolderIds = (folderId: string) => {
697→          folderIdsToRemove.push(folderId);
698→          const folders = useFolderStore.getState().folders;
699→          const folder = folders[folderId];
700→          if (!folder) return;
701→          for (const child of folder.children) {
702→            if (child.type === 'folder') {
703→              collectFolderIds(child.id);
704→            }
705→          }
706→        };
707→
708→        for (const item of items) {
709→          if (item.type === 'folder') {
710→            collectFolderIds(item.id);
711→          }
712→        }
713→
714→        // Snapshot the items to be removed before batch delete
715→        // (needed for addToBin after successful deletion)
716→        let removedChildren: FolderChild[] = [];
717→
718→        const performBatchDelete = async (): Promise<{
719→          updatedChildren: typeof parentFolder.children;
720→          newSequenceNumber: bigint;
721→        }> => {
722→          const freshParent = getParentFolder();
723→          if (!freshParent) throw new Error('Parent folder not found');
724→
725→          // Capture removed children before filtering
726→          removedChildren = freshParent.children.filter((c) => itemIds.has(c.id));
727→
728→          // Remove all items from parent's children in one pass
729→          const updatedChildren = freshParent.children.filter((c) => !itemIds.has(c.id));
730→
731→          // Single IPNS publish for the entire batch
732→          const { newSequenceNumber } = await folderService.updateFolderMetadata({
733→            folderId: freshParent.id,
734→            children: updatedChildren,
735→            folderKey: freshParent.folderKey,
736→            ipnsPrivateKey: freshParent.ipnsPrivateKey,
737→            ipnsName: freshParent.ipnsName,
738→            sequenceNumber: freshParent.sequenceNumber,
739→          });
740→
741→          return { updatedChildren, newSequenceNumber };
742→        };
743→
744→        const { updatedChildren, newSequenceNumber } = await withConflictRetry(
745→          performBatchDelete,
746→          () => resyncFolder(parentFolder.ipnsName, parentFolder.id)
747→        );
748→
749→        // Update local state -- remove all nested folders from store
750→        const store = useFolderStore.getState();
751→        store.updateFolderChildren(parentId, updatedChildren);
752→        store.updateFolderSequence(parentId, newSequenceNumber);
753→        for (const folderId of folderIdsToRemove) {
754→          store.removeFolder(folderId);
755→        }
756→
757→        // Fire-and-forget: add all deleted items to recycle bin (single IPNS publish)
758→        const auth = useAuthStore.getState();
759→        if (auth.vaultKeypair && removedChildren.length > 0) {
760→          const parentPath = buildFolderPath(parentId);
761→          void addManyToBin({
762→            items: removedChildren,
763→            parentIpnsName: parentFolder.ipnsName,
764→            parentPath,
765→            userPublicKey: auth.vaultKeypair.publicKey,
766→            userPrivateKey: auth.vaultKeypair.privateKey,
767→          }).catch(() => {
768→            console.error('[Delete] Failed to add batch to bin (non-blocking)');
769→          });
770→        }
771→
772→        setState({ isLoading: false, error: null });
773→      } catch (err) {
774→        const error = err instanceof Error ? err.message : 'Failed to delete items';
775→        setState({ isLoading: false, error });
776→        throw err;
777→      }
778→    },
779→    []
780→  );
781→
782→  return {
783→    ...state,
784→    createFolder: handleCreate,
785→    renameItem: handleRename,
786→    moveItem: handleMove,
787→    moveItems: handleMoveItems,
788→    deleteItem: handleDelete,
789→    deleteItems: handleDeleteItems,
790→  };
791→}
