  1→//! Write operations for macOS FUSE filesystem.
  2→//!
  3→//! Contains handler logic for: write, create, setattr, rename, unlink, rmdir, mkdir.
  4→
  5→#[cfg(feature = "fuse")]
  6→pub(crate) mod implementation {
  7→    use fuser::{
  8→        ReplyAttr, ReplyCreate, ReplyEmpty, ReplyEntry, ReplyWrite,
  9→    };
 10→    use std::ffi::OsStr;
 11→    use std::sync::atomic::Ordering;
 12→    use std::time::SystemTime;
 13→
 14→    use crate::fuse::CipherBoxFS;
 15→    use crate::fuse::file_handle::OpenFileHandle;
 16→    use crate::fuse::helpers::is_platform_special;
 17→    use crate::fuse::inode::{FileAttrs, InodeData, InodeKind};
 18→    use crate::fuse::operations::implementation::{
 19→        ttl_for_is_dir, current_uid, current_gid, FILE_TTL, DIR_TTL,
 20→    };
 21→
 22→    /// Set file attributes (handles truncate via size parameter).
 23→    pub fn handle_setattr(
 24→        fs: &mut CipherBoxFS,
 25→        ino: u64,
 26→        size: Option<u64>,
 27→        fh: Option<u64>,
 28→        reply: ReplyAttr,
 29→    ) {
 30→        log::debug!("setattr: ino={} size={:?} fh={:?}", ino, size, fh);
 31→        if let Some(new_size) = size {
 32→            if let Some(fh_id) = fh {
 33→                if let Some(handle) = fs.open_files.get_mut(&fh_id) {
 34→                    if handle.temp_path.is_some() {
 35→                        if let Err(e) = handle.truncate(new_size) {
 36→                            log::error!("Truncate failed for ino {}: {}", ino, e);
 37→                            reply.error(libc::EIO);
 38→                            return;
 39→                        }
 40→                        handle.dirty = true;
 41→                    }
 42→                }
 43→            } else {
 44→                // No explicit fh -- find open writable handle for this inode
 45→                let matching_fh: Option<u64> = fs.open_files.iter()
 46→                    .find(|(_, h)| h.ino == ino && h.temp_path.is_some())
 47→                    .map(|(id, _)| *id);
 48→                if let Some(fh_id) = matching_fh {
 49→                    if let Some(handle) = fs.open_files.get_mut(&fh_id) {
 50→                        if let Err(e) = handle.truncate(new_size) {
 51→                            log::error!("Truncate (no-fh) failed for ino {}: {}", ino, e);
 52→                            reply.error(libc::EIO);
 53→                            return;
 54→                        }
 55→                        handle.dirty = true;
 56→                    }
 57→                }
 58→            }
 59→
 60→            if let Some(inode) = fs.inodes.get_mut(ino) {
 61→                inode.attr.size = new_size;
 62→                inode.attr.blocks = (new_size + 511) / 512;
 63→                inode.attr.mtime = SystemTime::now();
 64→
 65→                if new_size == 0 {
 66→                    inode.write_generation += 1;
 67→                    if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
 68→                        *s = 0;
 69→                        *c = String::new();
 70→                    }
 71→                } else {
 72→                    if let InodeKind::File { size: ref mut s, .. } = inode.kind {
 73→                        *s = new_size;
 74→                    }
 75→                }
 76→
 77→                reply.attr(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()));
 78→                return;
 79→            }
 80→        }
 81→
 82→        if let Some(inode) = fs.inodes.get(ino) {
 83→            reply.attr(&ttl_for_is_dir(inode.attr.is_dir), &inode.attr.to_fuse_attr(current_uid(), current_gid()));
 84→        } else {
 85→            reply.error(libc::ENOENT);
 86→        }
 87→    }
 88→
 89→    /// Write data to an open file.
 90→    pub fn handle_write(
 91→        fs: &mut CipherBoxFS,
 92→        ino: u64,
 93→        fh: u64,
 94→        offset: i64,
 95→        data: &[u8],
 96→        reply: ReplyWrite,
 97→    ) {
 98→        let handle = match fs.open_files.get_mut(&fh) {
 99→            Some(h) => h,
100→            None => {
101→                reply.error(libc::EBADF);
102→                return;
103→            }
104→        };
105→
106→        match handle.write_at(offset, data) {
107→            Ok(written) => {
108→                let new_end = offset as u64 + data.len() as u64;
109→                if let Some(inode) = fs.inodes.get_mut(ino) {
110→                    if new_end > inode.attr.size {
111→                        inode.attr.size = new_end;
112→                        inode.attr.blocks = (new_end + 511) / 512;
113→                    }
114→                    inode.attr.mtime = SystemTime::now();
115→                }
116→                reply.written(written as u32);
117→            }
118→            Err(e) => {
119→                log::error!("Write failed for ino {} fh {}: {}", ino, fh, e);
120→                reply.error(libc::EIO);
121→            }
122→        }
123→    }
124→
125→    /// Create a new file in a directory.
126→    pub fn handle_create(
127→        fs: &mut CipherBoxFS,
128→        parent: u64,
129→        name: &OsStr,
130→        _flags: i32,
131→        reply: ReplyCreate,
132→    ) {
133→        let name_str = match name.to_str() {
134→            Some(n) => n,
135→            None => {
136→                reply.error(libc::EINVAL);
137→                return;
138→            }
139→        };
140→
141→        if is_platform_special(name_str) {
142→            reply.error(libc::EACCES);
143→            return;
144→        }
145→
146→        let parent_exists = fs.inodes.get(parent).map(|inode| {
147→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
148→        });
149→        if parent_exists != Some(true) {
150→            reply.error(libc::ENOENT);
151→            return;
152→        }
153→
154→        let ino = fs.inodes.allocate_ino();
155→        let now = SystemTime::now();
156→
157→        let attr = FileAttrs {
158→            ino,
159→            size: 0,
160→            blocks: 0,
161→            atime: now,
162→            mtime: now,
163→            ctime: now,
164→            crtime: now,
165→            is_dir: false,
166→            perm: 0o644,
167→            nlink: 1,
168→        };
169→        let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
170→
171→        // Generate random Ed25519 IPNS keypair for this file
172→        let signing_key = ed25519_dalek::SigningKey::generate(&mut rand::rngs::OsRng);
173→        let verifying_key = signing_key.verifying_key();
174→        let file_ipns_private_key = signing_key.to_bytes().to_vec();
175→        let file_ipns_public_key_bytes: [u8; 32] = verifying_key.to_bytes();
176→        let file_ipns_name = match crate::crypto::ipns::derive_ipns_name(&file_ipns_public_key_bytes) {
177→            Ok(name) => name,
178→            Err(e) => {
179→                log::error!("create: IPNS name derivation from random keypair failed: {}", e);
180→                reply.error(libc::EIO);
181→                return;
182→            }
183→        };
184→
185→        let ipns_key_encrypted_hex = match crate::crypto::ecies::wrap_key(&file_ipns_private_key, &fs.public_key) {
186→            Ok(wrapped) => Some(hex::encode(&wrapped)),
187→            Err(e) => {
188→                log::error!("create: failed to ECIES-wrap IPNS key: {}. Cannot proceed without wrapped key.", e);
189→                reply.error(libc::EIO);
190→                return;
191→            }
192→        };
193→
194→        let inode = InodeData {
195→            ino,
196→            parent_ino: parent,
197→            name: name_str.to_string(),
198→            kind: InodeKind::File {
199→                cid: String::new(),
200→                encrypted_file_key: String::new(),
201→                iv: String::new(),
202→                size: 0,
203→                encryption_mode: "GCM".to_string(),
204→                file_meta_ipns_name: Some(file_ipns_name),
205→                file_meta_resolved: true,
206→                file_ipns_private_key: Some(zeroize::Zeroizing::new(file_ipns_private_key)),
207→                file_ipns_key_encrypted_hex: ipns_key_encrypted_hex,
208→                versions: None,
209→            },
210→            attr,
211→            children: None,
212→            write_generation: 0,
213→        };
214→
215→        fs.inodes.insert(inode);
216→
217→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
218→            if let Some(ref mut children) = parent_inode.children {
219→                children.push(ino);
220→            }
221→            parent_inode.attr.mtime = SystemTime::now();
222→            parent_inode.attr.ctime = SystemTime::now();
223→        }
224→
225→        let fh = fs.next_fh.fetch_add(1, Ordering::SeqCst);
226→        match OpenFileHandle::new_write(ino, &fs.temp_dir, None) {
227→            Ok(handle) => {
228→                fs.open_files.insert(fh, handle);
229→            }
230→            Err(e) => {
231→                log::error!("Failed to create temp file for new file: {}", e);
232→                fs.inodes.remove(ino);
233→                if let Some(parent_inode) = fs.inodes.get_mut(parent) {
234→                    if let Some(ref mut children) = parent_inode.children {
235→                        children.retain(|&child| child != ino);
236→                    }
237→                }
238→                reply.error(libc::EIO);
239→                return;
240→            }
241→        }
242→
243→        fs.mutated_folders.insert(parent, std::time::Instant::now());
244→
245→        log::debug!("create: {} in parent {} -> ino {} fh {}", name_str, parent, ino, fh);
246→        reply.created(&FILE_TTL, &fuse_attr, 0, fh, 0);
247→    }
