407→    /// set_basic_info handler
408→    pub fn handle_set_basic_info(
409→        ctx: &WinFspContext,
410→        context: &WinFspFileContext,
411→        creation_time: u64,
412→        last_access_time: u64,
413→        last_write_time: u64,
414→        change_time: u64,
415→        file_info: &mut FileInfo,
416→    ) -> Result<(), FspError> {
417→        let mut fs = ctx.inner.lock().unwrap();
418→        if let Some(inode) = fs.inodes.get_mut(context.ino) {
419→            if creation_time != 0 {
420→                inode.attr.crtime = filetime_to_systemtime(creation_time);
421→            }
422→            if last_access_time != 0 {
423→                inode.attr.atime = filetime_to_systemtime(last_access_time);
424→            }
425→            if last_write_time != 0 {
426→                inode.attr.mtime = filetime_to_systemtime(last_write_time);
427→            }
428→            if change_time != 0 {
429→                inode.attr.ctime = filetime_to_systemtime(change_time);
430→            }
431→            *file_info = fill_file_info(&inode.attr);
432→        }
433→        Ok(())
434→    }
