436→    /// set_file_size handler
437→    pub fn handle_set_file_size(
438→        ctx: &WinFspContext,
439→        context: &WinFspFileContext,
440→        new_size: u64,
441→        set_allocation_size: bool,
442→        file_info: &mut FileInfo,
443→    ) -> Result<(), FspError> {
444→        log::info!(
445→            "set_file_size() ino={} fh={} new_size={} set_allocation_size={}",
446→            context.ino, context.fh, new_size, set_allocation_size
447→        );
448→        let mut fs = ctx.inner.lock().unwrap();
449→
450→        let should_truncate = !set_allocation_size
451→            || (set_allocation_size && new_size == 0);
452→
453→        if should_truncate {
454→            if let Some(handle) = fs.open_files.get_mut(&context.fh) {
455→                if handle.temp_path.is_some() {
456→                    handle.truncate(new_size).map_err(|_| status_io_device_error())?;
457→                    handle.dirty = true;
458→                    log::info!("set_file_size: truncated temp file to {} bytes", new_size);
459→                }
460→            }
461→
462→            if let Some(inode) = fs.inodes.get_mut(context.ino) {
463→                inode.attr.size = new_size;
464→                inode.attr.blocks = (new_size + 511) / 512;
465→                inode.attr.mtime = SystemTime::now();
466→                if let InodeKind::File { size: ref mut s, cid: ref mut c, .. } = inode.kind {
467→                    *s = new_size;
468→                    if new_size == 0 {
469→                        c.clear();
470→                    }
471→                }
472→                *file_info = fill_file_info(&inode.attr);
473→            }
474→        }
475→
476→        Ok(())
477→    }
