479→    /// cleanup handler (IRP_MJ_CLEANUP -- immediate on handle close)
480→    pub fn handle_cleanup(
481→        ctx: &WinFspContext,
482→        context: &WinFspFileContext,
483→        flags: u32,
484→    ) {
485→        log::info!(
486→            "cleanup() ino={} fh={} flags=0x{:08X}",
487→            context.ino, context.fh, flags
488→        );
489→        let mut fs = ctx.inner.lock().unwrap();
490→        let ino = context.ino;
491→        let fh = context.fh;
492→
493→        // FspCleanupDelete = 0x01
494→        if flags & 0x01 != 0 {
495→            let (parent_ino, cid_to_unpin) = match fs.inodes.get(ino) {
496→                Some(inode) => {
497→                    let parent = inode.parent_ino;
498→                    let cid = match &inode.kind {
499→                        InodeKind::File { cid, .. } => {
500→                            if cid.is_empty() { None } else { Some(cid.clone()) }
501→                        }
502→                        InodeKind::Folder { ipns_name, .. } => {
503→                            fs.metadata_cache.get(ipns_name).map(|cached| cached.cid.clone())
504→                        }
505→                        _ => None,
506→                    };
507→                    (parent, cid)
508→                }
509→                None => return,
510→            };
511→
512→            fs.inodes.remove(ino);
513→
514→            if let Some(parent_inode) = fs.inodes.get_mut(parent_ino) {
515→                parent_inode.attr.mtime = SystemTime::now();
516→                parent_inode.attr.ctime = SystemTime::now();
517→            }
518→
519→            if let Err(e) = fs.update_folder_metadata(parent_ino) {
520→                log::error!("Failed to update folder metadata after delete: {}", e);
521→            }
522→
523→            if let Some(cid) = cid_to_unpin {
524→                let api = fs.api.clone();
525→                fs.rt.spawn(async move {
526→                    let _ = crate::api::ipfs::unpin_content(&api, &cid).await;
527→                });
528→            }
529→        } else {
530→            // Non-delete cleanup: flush dirty file handles
531→            fs.drain_upload_completions();
532→
533→            let needs_flush = fs.open_files.get(&fh)
534→                .map(|h| {
535→                    let has_temp = h.temp_path.is_some();
536→                    let is_new = has_temp && fs.inodes.get(ino)
537→                        .map(|i| match &i.kind {
538→                            InodeKind::File { cid, .. } => cid.is_empty(),
539→                            _ => false,
540→                        })
541→                        .unwrap_or(false);
542→                    has_temp && (h.dirty || is_new)
543→                })
544→                .unwrap_or(false);
545→
546→            if needs_flush {
547→                let handle = fs.open_files.remove(&fh).unwrap();
548→
549→                let prepare_result = (|| -> Result<(), String> {
550→                    let plaintext = handle.read_all()?;
551→                    let mut file_key = crate::crypto::utils::generate_file_key();
552→                    let iv = crate::crypto::utils::generate_iv();
553→                    let ciphertext = crate::crypto::aes::encrypt_aes_gcm(
554→                        &plaintext, &file_key, &iv,
555→                    )
556→                    .map_err(|e| format!("File encryption failed: {}", e))?;
557→                    let wrapped_key = crate::crypto::ecies::wrap_key(&file_key, &fs.public_key)
558→                        .map_err(|e| format!("Key wrapping failed: {}", e))?;
559→                    crate::crypto::utils::clear_bytes(&mut file_key);
560→
561→                    let (old_file_cid, _old_encrypted_key, _old_iv, old_size, old_mode,
562→                         existing_versions, file_ipns_private_key, file_meta_ipns_name) =
563→                        fs.inodes.get(ino).map(|inode| match &inode.kind {
564→                            InodeKind::File {
565→                                cid, encrypted_file_key, iv, size, encryption_mode,
566→                                versions, file_ipns_private_key, file_meta_ipns_name, ..
567→                            } => (
568→                                if cid.is_empty() { None } else { Some(cid.clone()) },
569→                                encrypted_file_key.clone(), iv.clone(), *size,
570→                                encryption_mode.clone(), versions.clone(),
571→                                file_ipns_private_key.clone(), file_meta_ipns_name.clone(),
572→                            ),
573→                            _ => (None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None),
574→                        }).unwrap_or((None, String::new(), String::new(), 0, "GCM".to_string(), None, None, None));
575→
576→                    let encrypted_file_key_hex = hex::encode(&wrapped_key);
577→                    let iv_hex = hex::encode(&iv);
578→                    let file_size = plaintext.len() as u64;
579→                    let file_name = fs.inodes.get(ino).map(|i| i.name.clone()).unwrap_or_default();
580→                    let mime_type = mime_from_extension(&file_name);
581→
582→                    let now_ms = SystemTime::now()
583→                        .duration_since(UNIX_EPOCH)
584→                        .unwrap_or_default()
585→                        .as_millis() as u64;
586→
587→                    let should_version = if let Some(ref versions) = existing_versions {
588→                        if let Some(newest) = versions.first() {
589→                            now_ms.saturating_sub(newest.timestamp) >= VERSION_COOLDOWN_MS
590→                        } else {
591→                            old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
592→                        }
593→                    } else {
594→                        old_file_cid.as_ref().is_some_and(|c| !c.is_empty())
595→                    };
596→
597→                    let (new_versions, pruned_cids) = if should_version {
598→                        if let Some(ref old_c) = old_file_cid {
599→                            if !old_c.is_empty() {
600→                                let version_entry = crate::crypto::folder::VersionEntry {
601→                                    cid: old_c.clone(),
602→                                    file_key_encrypted: _old_encrypted_key.clone(),
603→                                    file_iv: _old_iv.clone(),
604→                                    size: old_size,
605→                                    timestamp: now_ms,
606→                                    encryption_mode: old_mode.clone(),
607→                                };
608→                                let mut versions = vec![version_entry];
609→                                versions.extend(existing_versions.unwrap_or_default());
610→                                let pruned: Vec<String> = if versions.len() > MAX_VERSIONS_PER_FILE {
611→                                    versions.split_off(MAX_VERSIONS_PER_FILE).into_iter().map(|v| v.cid).collect()
612→                                } else {
613→                                    vec![]
614→                                };
615→                                (Some(versions), pruned)
616→                            } else {
617→                                (existing_versions, vec![])
618→                            }
619→                        } else {
620→                            (existing_versions, vec![])
621→                        }
622→                    } else {
623→                        (existing_versions, vec![])
624→                    };
625→
626→                    let versions_for_meta = new_versions.as_ref()
627→                        .filter(|v| !v.is_empty())
628→                        .cloned();
629→
630→                    if let Some(inode) = fs.inodes.get_mut(ino) {
631→                        let cached_hex = match &inode.kind {
632→                            InodeKind::File { file_ipns_key_encrypted_hex, .. } => file_ipns_key_encrypted_hex.clone(),
633→                            _ => None,
634→                        };
635→                        inode.kind = InodeKind::File {
636→                            cid: String::new(),
637→                            encrypted_file_key: encrypted_file_key_hex.clone(),
638→                            iv: iv_hex.clone(),
639→                            size: file_size,
640→                            encryption_mode: "GCM".to_string(),
641→                            file_meta_ipns_name: file_meta_ipns_name.clone(),
642→                            file_meta_resolved: true,
643→                            file_ipns_private_key: file_ipns_private_key.clone(),
644→                            file_ipns_key_encrypted_hex: cached_hex,
645→                            versions: versions_for_meta.clone(),
646→                        };
647→                        inode.attr.size = file_size;
648→                        inode.attr.blocks = (file_size + 511) / 512;
649→                        inode.attr.mtime = SystemTime::now();
650→                    }
651→
652→                    fs.pending_content.insert(ino, plaintext);
653→
654→                    let parent_ino = fs.inodes.get(ino).map(|i| i.parent_ino).unwrap_or(ROOT_INO);
655→                    let folder_key_for_file_meta = fs.get_folder_key(parent_ino);
656→                    fs.queue_publish(parent_ino, true);
657→
658→                    let api = fs.api.clone();
659→                    let rt = fs.rt.clone();
660→                    let upload_tx = fs.upload_tx.clone();
661→                    let coordinator = fs.publish_coordinator.clone();
662→
663→                    let file_meta = crate::crypto::folder::FileMetadata {
664→                        version: "v1".to_string(),
665→                        cid: String::new(),
666→                        file_key_encrypted: encrypted_file_key_hex,
667→                        file_iv: iv_hex,
668→                        size: file_size,
669→                        mime_type,
670→                        encryption_mode: "GCM".to_string(),
671→                        created_at: now_ms,
672→                        modified_at: now_ms,
673→                        versions: versions_for_meta,
674→                    };
675→
676→                    std::thread::spawn(move || {
677→                        let result = rt.block_on(async {
678→                            let file_cid = crate::api::ipfs::upload_content(&api, &ciphertext).await?;
679→                            log::info!("File uploaded: ino {} -> CID {}", ino, file_cid);
680→
681→                            let _ = upload_tx.send(crate::fuse::UploadComplete {
682→                                ino,
683→                                new_cid: file_cid.clone(),
684→                                parent_ino,
685→                                old_file_cid,
686→                                pruned_cids,
687→                                write_generation: 0,
688→                            });
689→
690→                            if let (Some(ipns_key), Some(ipns_name), Some(folder_key)) =
691→                                (&file_ipns_private_key, &file_meta_ipns_name, &folder_key_for_file_meta)
692→                            {
693→                                let mut file_meta_with_cid = file_meta;
694→                                file_meta_with_cid.cid = file_cid;
695→                                if let Err(e) = publish_file_metadata(
696→                                    &api, &file_meta_with_cid, folder_key, ipns_key, ipns_name, &coordinator,
697→                                ).await {
698→                                    log::warn!("Per-file IPNS publish failed for ino {}: {}", ino, e);
699→                                }
700→                            }
701→
702→                            Ok::<(), String>(())
703→                        });
704→
705→                        if let Err(e) = result {
706→                            log::error!("Background upload failed for ino {}: {}", ino, e);
707→                        }
708→                    });
709→
710→                    Ok(())
711→                })();
712→
713→                if let Err(e) = prepare_result {
714→                    log::error!("File upload preparation failed for ino {}: {}", ino, e);
715→                }
716→
717→                handle.cleanup();
718→            }
719→        }
720→    }
