722→    /// rename handler
723→    pub fn handle_rename(
724→        ctx: &WinFspContext,
725→        file_name: &U16CStr,
726→        new_file_name: &U16CStr,
727→        replace_if_exists: bool,
728→    ) -> Result<(), FspError> {
729→        let old_path = file_name.to_string_lossy();
730→        let new_path = new_file_name.to_string_lossy();
731→
732→        let mut fs = ctx.inner.lock().unwrap();
733→
734→        let (source_ino, old_parent_ino) = resolve_path(&fs, &old_path)
735→            .ok_or(status_object_name_not_found())?;
736→
737→        let (new_parent_path, new_name) = split_path(&new_path);
738→        let (new_parent_ino, _) = resolve_path(&fs, new_parent_path)
739→            .ok_or(status_object_name_not_found())?;
740→
741→        if let Some(dest_ino) = fs.inodes.find_child(new_parent_ino, new_name) {
742→            if !replace_if_exists {
743→                return Err(status_object_name_collision());
744→            }
745→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
746→                match &dest_inode.kind {
747→                    InodeKind::Folder { .. } => {
748→                        if let Some(ref children) = dest_inode.children {
749→                            if !children.is_empty() {
750→                                return Err(status_directory_not_empty());
751→                            }
752→                        }
753→                    }
754→                    InodeKind::File { cid, .. } => {
755→                        if !cid.is_empty() {
756→                            let cid_clone = cid.clone();
757→                            let api = fs.api.clone();
758→                            fs.rt.spawn(async move {
759→                                let _ = crate::api::ipfs::unpin_content(&api, &cid_clone).await;
760→                            });
761→                        }
762→                    }
763→                    _ => {}
764→                }
765→            }
766→            fs.inodes.remove(dest_ino);
767→        }
768→
769→        let old_name = fs.inodes.get(source_ino).map(|i| i.name.clone()).unwrap_or_default();
770→        fs.inodes.name_to_ino.remove(&(
771→            old_parent_ino,
772→            crate::fuse::inode::normalize_name(&old_name),
773→        ));
774→
775→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
776→            inode.name = new_name.to_string();
777→            inode.parent_ino = new_parent_ino;
778→            inode.attr.ctime = SystemTime::now();
779→        }
780→
781→        fs.inodes.name_to_ino.insert(
782→            (new_parent_ino, crate::fuse::inode::normalize_name(new_name)),
783→            source_ino,
784→        );
785→
786→        if old_parent_ino != new_parent_ino {
787→            if let Some(old_parent) = fs.inodes.get_mut(old_parent_ino) {
788→                if let Some(ref mut children) = old_parent.children {
789→                    children.retain(|&c| c != source_ino);
790→                }
791→                old_parent.attr.mtime = SystemTime::now();
792→                old_parent.attr.ctime = SystemTime::now();
793→            }
794→            if let Some(new_parent) = fs.inodes.get_mut(new_parent_ino) {
795→                if let Some(ref mut children) = new_parent.children {
796→                    children.push(source_ino);
797→                }
798→                new_parent.attr.mtime = SystemTime::now();
799→                new_parent.attr.ctime = SystemTime::now();
800→            }
801→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
802→                log::error!("Failed to update old parent metadata after rename: {}", e);
803→            }
804→            if let Err(e) = fs.update_folder_metadata(new_parent_ino) {
805→                log::error!("Failed to update new parent metadata after rename: {}", e);
806→            }
807→        } else {
808→            if let Some(parent_inode) = fs.inodes.get_mut(old_parent_ino) {
809→                parent_inode.attr.mtime = SystemTime::now();
810→                parent_inode.attr.ctime = SystemTime::now();
811→            }
812→            if let Err(e) = fs.update_folder_metadata(old_parent_ino) {
813→                log::error!("Failed to update parent metadata after rename: {}", e);
814→            }
815→        }
816→
817→        Ok(())
818→    }
