 89→    /// Write data to an open file.
 90→    pub fn handle_write(
 91→        fs: &mut CipherBoxFS,
 92→        ino: u64,
 93→        fh: u64,
 94→        offset: i64,
 95→        data: &[u8],
 96→        reply: ReplyWrite,
 97→    ) {
 98→        let handle = match fs.open_files.get_mut(&fh) {
 99→            Some(h) => h,
100→            None => {
101→                reply.error(libc::EBADF);
102→                return;
103→            }
104→        };
105→
106→        match handle.write_at(offset, data) {
107→            Ok(written) => {
108→                let new_end = offset as u64 + data.len() as u64;
109→                if let Some(inode) = fs.inodes.get_mut(ino) {
110→                    if new_end > inode.attr.size {
111→                        inode.attr.size = new_end;
112→                        inode.attr.blocks = (new_end + 511) / 512;
113→                    }
114→                    inode.attr.mtime = SystemTime::now();
115→                }
116→                reply.written(written as u32);
117→            }
118→            Err(e) => {
119→                log::error!("Write failed for ino {} fh {}: {}", ino, fh, e);
120→                reply.error(libc::EIO);
121→            }
122→        }
123→    }
