249→    /// Delete a file from a directory.
250→    pub fn handle_unlink(
251→        fs: &mut CipherBoxFS,
252→        parent: u64,
253→        name: &OsStr,
254→        reply: ReplyEmpty,
255→    ) {
256→        let name_str = match name.to_str() {
257→            Some(n) => n,
258→            None => {
259→                reply.error(libc::ENOENT);
260→                return;
261→            }
262→        };
263→
264→        let child_ino = match fs.inodes.find_child(parent, name_str) {
265→            Some(ino) => ino,
266→            None => {
267→                reply.error(libc::ENOENT);
268→                return;
269→            }
270→        };
271→
272→        // Capture data for bin entry before inode removal
273→        let bin_entry_data = match fs.inodes.get(child_ino) {
274→            Some(inode) => match &inode.kind {
275→                InodeKind::File {
276→                    file_meta_ipns_name,
277→                    file_ipns_key_encrypted_hex,
278→                    size,
279→                    ..
280→                } => {
281→                    let now_ms = SystemTime::now()
282→                        .duration_since(std::time::UNIX_EPOCH)
283→                        .unwrap_or_default()
284→                        .as_millis() as u64;
285→                    let created_ms = inode.attr.crtime
286→                        .duration_since(std::time::UNIX_EPOCH)
287→                        .unwrap_or_default()
288→                        .as_millis() as u64;
289→
290→                    let meta_ipns = match file_meta_ipns_name {
291→                        Some(name) if !name.is_empty() => Some(name.clone()),
292→                        _ => {
293→                            // file_meta_ipns_name is optional for files loaded from
294→                            // remote metadata before IPNS resolve. Since bin publishing
295→                            // is best-effort, skip creating a bin entry when it's missing
296→                            // instead of failing the unlink.
297→                            log::warn!(
298→                                "unlink: missing file_meta_ipns_name for ino {}, skipping bin entry",
299→                                child_ino
300→                            );
301→                            None
302→                        }
303→                    };
304→
305→                    if let Some(meta_ipns) = meta_ipns {
306→                        let file_pointer = crate::crypto::folder::FilePointer {
307→                            id: crate::crypto::utils::generate_uuid_v4(),
308→                            name: inode.name.clone(),
309→                            file_meta_ipns_name: meta_ipns,
310→                            ipns_private_key_encrypted: file_ipns_key_encrypted_hex.clone(),
311→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
312→                            modified_at: now_ms,
313→                        };
314→
315→                        Some((inode.name.clone(), *size, file_pointer))
316→                    } else {
317→                        None
318→                    }
319→                }
320→                _ => {
321→                    reply.error(libc::EISDIR);
322→                    return;
323→                }
324→            },
325→            None => {
326→                reply.error(libc::ENOENT);
327→                return;
328→            }
329→        };
330→
331→        log::debug!("unlink: {} from parent {}", name_str, parent);
332→
333→        let now = SystemTime::now();
334→
335→        fs.inodes.remove(child_ino);
336→
337→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
338→            parent_inode.attr.mtime = now;
339→            parent_inode.attr.ctime = now;
340→        }
341→
342→        if let Err(e) = fs.update_folder_metadata(parent) {
343→            log::error!("Failed to update folder metadata after unlink: {}", e);
344→        }
345→
346→        // Create bin entry and publish to bin IPNS (fire-and-forget)
347→        if let Some((item_name, file_size, file_pointer)) = bin_entry_data {
348→            let parent_ipns_name = fs.inodes.get(parent)
349→                .map(|p| match &p.kind {
350→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
351→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
352→                    _ => String::new(),
353→                })
354→                .unwrap_or_default();
355→
356→            if parent_ipns_name.is_empty() {
357→                log::warn!(
358→                    "unlink: missing parent IPNS name for parent ino {}, skipping bin publish",
359→                    parent
360→                );
361→            } else {
362→                let parent_path = build_folder_path(fs, parent);
363→
364→                let bin_entry = crate::crypto::bin::BinEntry {
365→                    id: crate::crypto::utils::generate_uuid_v4(),
366→                    item_type: crate::crypto::bin::BinItemType::File,
367→                    name: item_name.clone(),
368→                    original_parent_ipns_name: parent_ipns_name,
369→                    original_path: parent_path,
370→                    deleted_at: now
371→                        .duration_since(std::time::UNIX_EPOCH)
372→                        .unwrap_or_default()
373→                        .as_millis() as u64,
374→                    size: file_size,
375→                    mime_type: crate::crypto::utils::mime_from_extension(&item_name).to_string(),
376→                    file_pointer: Some(file_pointer),
377→                    folder_entry: None,
378→                };
379→
380→                crate::fuse::spawn_bin_entry_publish(
381→                    fs.api.clone(),
382→                    fs.rt.clone(),
383→                    bin_entry,
384→                    fs.private_key.clone(),
385→                    fs.public_key.to_vec(),
386→                    fs.publish_coordinator.clone(),
387→                );
388→            }
389→        }
390→
391→        reply.ok();
392→    }
