394→    /// Create a new directory.
395→    pub fn handle_mkdir(
396→        fs: &mut CipherBoxFS,
397→        parent: u64,
398→        name: &OsStr,
399→        reply: ReplyEntry,
400→    ) {
401→        let name_str = match name.to_str() {
402→            Some(n) => n,
403→            None => {
404→                reply.error(libc::EINVAL);
405→                return;
406→            }
407→        };
408→
409→        if is_platform_special(name_str) {
410→            reply.error(libc::EACCES);
411→            return;
412→        }
413→
414→        let parent_exists = fs.inodes.get(parent).map(|inode| {
415→            matches!(inode.kind, InodeKind::Root { .. } | InodeKind::Folder { .. })
416→        });
417→        if parent_exists != Some(true) {
418→            reply.error(libc::ENOENT);
419→            return;
420→        }
421→
422→        log::debug!("mkdir: {} in parent {}", name_str, parent);
423→
424→        let result = (|| -> Result<fuser::FileAttr, String> {
425→            let folder_key = crate::crypto::utils::generate_file_key();
426→
427→            let (ipns_public_key, ipns_private_key) =
428→                crate::crypto::ed25519::generate_ed25519_keypair();
429→
430→            let ipns_pub_arr: [u8; 32] = ipns_public_key.clone().try_into()
431→                .map_err(|_| "Invalid IPNS public key length".to_string())?;
432→            let ipns_name = crate::crypto::ipns::derive_ipns_name(&ipns_pub_arr)
433→                .map_err(|e| format!("Failed to derive IPNS name: {}", e))?;
434→
435→            let wrapped_folder_key = crate::crypto::ecies::wrap_key(
436→                &folder_key, &fs.public_key,
437→            )
438→            .map_err(|e| format!("Folder key wrapping failed: {}", e))?;
439→            let encrypted_folder_key_hex = hex::encode(&wrapped_folder_key);
440→
441→            let ino = fs.inodes.allocate_ino();
442→            let now = SystemTime::now();
443→
444→            let attr = FileAttrs {
445→                ino,
446→                size: 0,
447→                blocks: 0,
448→                atime: now,
449→                mtime: now,
450→                ctime: now,
451→                crtime: now,
452→                is_dir: true,
453→                perm: 0o755,
454→                nlink: 2,
455→            };
456→            let fuse_attr = attr.to_fuse_attr(current_uid(), current_gid());
457→
458→            let inode = InodeData {
459→                ino,
460→                parent_ino: parent,
461→                name: name_str.to_string(),
462→                kind: InodeKind::Folder {
463→                    ipns_name: ipns_name.clone(),
464→                    encrypted_folder_key: encrypted_folder_key_hex,
465→                    folder_key: zeroize::Zeroizing::new(folder_key.to_vec()),
466→                    ipns_private_key: Some(zeroize::Zeroizing::new(ipns_private_key.clone())),
467→                    children_loaded: true,
468→                },
469→                attr,
470→                children: Some(vec![]),
471→                write_generation: 0,
472→            };
473→
474→            fs.inodes.insert(inode);
475→
476→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
477→                if let Some(ref mut children) = parent_inode.children {
478→                    children.push(ino);
479→                }
480→                parent_inode.attr.mtime = SystemTime::now();
481→                parent_inode.attr.ctime = SystemTime::now();
482→            }
483→
484→            let metadata = crate::crypto::folder::FolderMetadata {
485→                version: "v2".to_string(),
486→                children: vec![],
487→            };
488→
489→            let json_bytes = crate::fuse::encrypt_metadata_to_json(
490→                &metadata, &folder_key,
491→            )?;
492→
493→            let encrypted_ipns_for_tee = if let Some(ref tee_key) = fs.tee_public_key {
494→                let wrapped = crate::crypto::ecies::wrap_key(&ipns_private_key, tee_key)
495→                    .map_err(|e| format!("TEE key wrapping failed: {}", e))?;
496→                Some(hex::encode(&wrapped))
497→            } else {
498→                None
499→            };
500→            let tee_key_epoch = fs.tee_key_epoch;
501→
502→            let (parent_metadata, parent_folder_key, parent_ipns_key, parent_ipns_name, parent_old_cid) =
503→                fs.build_folder_metadata(parent)?;
504→
505→            let api = fs.api.clone();
506→            let rt = fs.rt.clone();
507→            let ipns_name_clone = ipns_name.clone();
508→            let coordinator = fs.publish_coordinator.clone();
509→
510→            std::thread::spawn(move || {
511→                let result = rt.block_on(async {
512→                    let initial_cid = crate::api::ipfs::upload_content(
513→                        &api, &json_bytes,
514→                    ).await?;
515→
516→                    let ipns_key_arr: [u8; 32] = ipns_private_key.try_into()
517→                        .map_err(|_| "Invalid IPNS key length".to_string())?;
518→                    let value = format!("/ipfs/{}", initial_cid);
519→                    let record = crate::crypto::ipns::create_ipns_record(
520→                        &ipns_key_arr, &value, 0, 86_400_000,
521→                    ).map_err(|e| format!("IPNS record creation failed: {}", e))?;
522→                    let marshaled = crate::crypto::ipns::marshal_ipns_record(&record)
523→                        .map_err(|e| format!("IPNS marshal failed: {}", e))?;
524→
525→                    use base64::Engine;
526→                    let record_b64 = base64::engine::general_purpose::STANDARD
527→                        .encode(&marshaled);
528→
529→                    // New folder initial publish: sequence 0, no conflict check needed
530→                    let req = crate::api::ipns::IpnsPublishRequest {
531→                        ipns_name: ipns_name_clone.clone(),
532→                        record: record_b64,
533→                        metadata_cid: initial_cid,
534→                        encrypted_ipns_private_key: encrypted_ipns_for_tee,
535→                        key_epoch: tee_key_epoch,
536→                        expected_sequence_number: None,
537→                    };
538→                    match crate::api::ipns::publish_ipns(&api, &req).await? {
539→                        crate::api::ipns::PublishResult::Success => {
540→                            coordinator.record_publish(&ipns_name_clone, 0);
541→                            log::info!("New folder IPNS published: {}", ipns_name_clone);
542→                        }
543→                        crate::api::ipns::PublishResult::Conflict { .. } => {
544→                            // Sequence 0 should never conflict -- log and continue
545→                            log::warn!("Unexpected conflict on new folder IPNS publish for {}", ipns_name_clone);
546→                        }
547→                    }
548→
549→                    let lock = coordinator.get_lock(&parent_ipns_name);
550→                    let _guard = lock.lock().await;
551→
552→                    let parent_json = crate::fuse::encrypt_metadata_to_json(
553→                        &parent_metadata, &parent_folder_key,
554→                    )?;
555→
556→                    let seq = coordinator.resolve_sequence(&api, &parent_ipns_name).await?;
557→
558→                    let parent_meta_cid = crate::api::ipfs::upload_content(
559→                        &api, &parent_json,
560→                    ).await?;
561→
562→                    let parent_key_arr: [u8; 32] = parent_ipns_key.try_into()
563→                        .map_err(|_| "Invalid parent IPNS key length".to_string())?;
564→                    let new_seq = seq + 1;
565→                    let parent_value = format!("/ipfs/{}", parent_meta_cid);
566→                    let parent_record = crate::crypto::ipns::create_ipns_record(
567→                        &parent_key_arr, &parent_value, new_seq, 86_400_000,
568→                    ).map_err(|e| format!("Parent IPNS record failed: {}", e))?;
569→                    let parent_marshaled = crate::crypto::ipns::marshal_ipns_record(
570→                        &parent_record,
571→                    ).map_err(|e| format!("Parent IPNS marshal failed: {}", e))?;
572→                    let parent_record_b64 = base64::engine::general_purpose::STANDARD
573→                        .encode(&parent_marshaled);
574→
575→                    // Parent folder publish after mkdir includes conflict detection.
576→                    // On conflict, log a warning -- the debounced publish queue will
577→                    // retry the parent metadata on the next cycle.
578→                    // TODO: Add full re-fetch+merge+retry for parent mkdir publish (v2).
579→                    let parent_req = crate::api::ipns::IpnsPublishRequest {
580→                        ipns_name: parent_ipns_name.clone(),
581→                        record: parent_record_b64,
582→                        metadata_cid: parent_meta_cid,
583→                        encrypted_ipns_private_key: None,
584→                        key_epoch: None,
585→                        expected_sequence_number: Some(seq.to_string()),
586→                    };
587→                    match crate::api::ipns::publish_ipns(&api, &parent_req).await? {
588→                        crate::api::ipns::PublishResult::Success => {
589→                            coordinator.record_publish(&parent_ipns_name, new_seq);
590→                            // Only unpin old CID on successful publish
591→                            if let Some(old) = parent_old_cid {
592→                                let _ = crate::api::ipfs::unpin_content(&api, &old).await;
593→                            }
594→                            log::info!("Parent metadata published after mkdir");
595→                        }
596→                        crate::api::ipns::PublishResult::Conflict { current_sequence_number } => {
597→                            log::warn!(
598→                                "Conflict on parent publish after mkdir (expected seq {}, server has {}). \
599→                                Debounced publish will retry.",
600→                                seq, current_sequence_number
601→                            );
602→                            // Do not record_publish or unpin -- let the next debounced publish pick up fresh seq
603→                        }
604→                    }
605→                    Ok::<(), String>(())
606→                });
607→
608→                if let Err(e) = result {
609→                    log::error!("Background mkdir publish failed: {}", e);
610→                }
611→            });
612→
613→            Ok(fuse_attr)
614→        })();
615→
616→        match result {
617→            Ok(fuse_attr) => {
618→                reply.entry(&DIR_TTL, &fuse_attr, 0);
619→            }
620→            Err(e) => {
621→                log::error!("mkdir failed: {}", e);
622→                reply.error(libc::EIO);
623→            }
624→        }
625→    }
626→
627→    /// Remove an empty directory.
628→    pub fn handle_rmdir(
629→        fs: &mut CipherBoxFS,
630→        parent: u64,
631→        name: &OsStr,
632→        reply: ReplyEmpty,
633→    ) {
634→        let name_str = match name.to_str() {
635→            Some(n) => n,
636→            None => {
637→                reply.error(libc::ENOENT);
638→                return;
639→            }
640→        };
641→
642→        let child_ino = match fs.inodes.find_child(parent, name_str) {
643→            Some(ino) => ino,
644→            None => {
645→                reply.error(libc::ENOENT);
646→                return;
647→            }
648→        };
649→
650→        // Capture folder data for bin entry before inode removal
651→        let bin_entry_data = match fs.inodes.get(child_ino) {
652→            Some(inode) => {
653→                match &inode.kind {
654→                    InodeKind::Folder {
655→                        ipns_name,
656→                        encrypted_folder_key,
657→                        ipns_private_key,
658→                        ..
659→                    } => {
660→                        // Check for non-empty folder (POSIX requirement)
661→                        if let Some(ref children) = inode.children {
662→                            if !children.is_empty() {
663→                                reply.error(libc::ENOTEMPTY);
664→                                return;
665→                            }
666→                        }
667→
668→                        let now_ms = SystemTime::now()
669→                            .duration_since(std::time::UNIX_EPOCH)
670→                            .unwrap_or_default()
671→                            .as_millis() as u64;
672→                        let created_ms = inode.attr.crtime
673→                            .duration_since(std::time::UNIX_EPOCH)
674→                            .unwrap_or_default()
675→                            .as_millis() as u64;
676→
677→                        // Build the ECIES-wrapped IPNS private key for the FolderEntry
678→                        let ipns_key_encrypted = match ipns_private_key {
679→                            Some(key) => match crate::crypto::ecies::wrap_key(key, &fs.public_key) {
680→                                Ok(wrapped) => hex::encode(&wrapped),
681→                                Err(e) => {
682→                                    log::error!("rmdir: failed to wrap IPNS key for bin entry: {}", e);
683→                                    reply.error(libc::EIO);
684→                                    return;
685→                                }
686→                            },
687→                            None => {
688→                                log::error!("rmdir: missing folder IPNS private key for ino {}", child_ino);
689→                                reply.error(libc::EIO);
690→                                return;
691→                            }
692→                        };
693→
694→                        let folder_entry = crate::crypto::folder::FolderEntry {
695→                            id: crate::crypto::utils::generate_uuid_v4(),
696→                            name: inode.name.clone(),
697→                            ipns_name: ipns_name.clone(),
698→                            folder_key_encrypted: encrypted_folder_key.clone(),
699→                            ipns_private_key_encrypted: ipns_key_encrypted,
700→                            created_at: if created_ms > 0 { created_ms } else { now_ms },
701→                            modified_at: now_ms,
702→                        };
703→
704→                        Some((inode.name.clone(), folder_entry))
705→                    }
706→                    _ => {
707→                        reply.error(libc::ENOTDIR);
708→                        return;
709→                    }
710→                }
711→            }
712→            None => {
713→                reply.error(libc::ENOENT);
714→                return;
715→            }
716→        };
717→
718→        log::debug!("rmdir: {} from parent {}", name_str, parent);
719→
720→        let now = SystemTime::now();
721→
722→        fs.inodes.remove(child_ino);
723→
724→        if let Some(parent_inode) = fs.inodes.get_mut(parent) {
725→            parent_inode.attr.mtime = now;
726→            parent_inode.attr.ctime = now;
727→        }
728→
729→        if let Err(e) = fs.update_folder_metadata(parent) {
730→            log::error!("Failed to update folder metadata after rmdir: {}", e);
731→        }
732→
733→        // Create bin entry and publish to bin IPNS (fire-and-forget)
734→        if let Some((item_name, folder_entry)) = bin_entry_data {
735→            let parent_ipns_name = fs.inodes.get(parent)
736→                .map(|p| match &p.kind {
737→                    InodeKind::Root { ipns_name, .. } => ipns_name.clone().unwrap_or_default(),
738→                    InodeKind::Folder { ipns_name, .. } => ipns_name.clone(),
739→                    _ => String::new(),
740→                })
741→                .unwrap_or_default();
742→
743→            if parent_ipns_name.is_empty() {
744→                log::warn!(
745→                    "rmdir: missing parent IPNS name for parent ino {}, skipping bin publish",
746→                    parent
747→                );
748→            } else {
749→                let parent_path = build_folder_path(fs, parent);
750→
751→                let bin_entry = crate::crypto::bin::BinEntry {
752→                    id: crate::crypto::utils::generate_uuid_v4(),
753→                    item_type: crate::crypto::bin::BinItemType::Folder,
754→                    name: item_name,
755→                    original_parent_ipns_name: parent_ipns_name,
756→                    original_path: parent_path,
757→                    deleted_at: now
758→                        .duration_since(std::time::UNIX_EPOCH)
759→                        .unwrap_or_default()
760→                        .as_millis() as u64,
761→                    size: 0,
762→                    mime_type: String::new(),
763→                    file_pointer: None,
764→                    folder_entry: Some(folder_entry),
765→                };
766→
767→                crate::fuse::spawn_bin_entry_publish(
768→                    fs.api.clone(),
769→                    fs.rt.clone(),
770→                    bin_entry,
771→                    fs.private_key.clone(),
772→                    fs.public_key.to_vec(),
773→                    fs.publish_coordinator.clone(),
774→                );
775→            }
776→        }
777→
778→        reply.ok();
779→    }
