781→    /// Rename or move a file/folder.
782→    pub fn handle_rename(
783→        fs: &mut CipherBoxFS,
784→        parent: u64,
785→        name: &OsStr,
786→        newparent: u64,
787→        newname: &OsStr,
788→        reply: ReplyEmpty,
789→    ) {
790→        log::debug!(
791→            "rename: {:?} (parent {}) -> {:?} (parent {})",
792→            name, parent, newname, newparent,
793→        );
794→        let name_str = match name.to_str() {
795→            Some(n) => n,
796→            None => {
797→                reply.error(libc::EINVAL);
798→                return;
799→            }
800→        };
801→        let newname_str = match newname.to_str() {
802→            Some(n) => n,
803→            None => {
804→                reply.error(libc::EINVAL);
805→                return;
806→            }
807→        };
808→
809→        // Find source inode (with FUSE-T truncated name fallback)
810→        let (source_ino, actual_name) = match fs.inodes.find_child(parent, name_str) {
811→            Some(ino) => (ino, name_str.to_string()),
812→            None => {
813→                let parent_inode = match fs.inodes.get(parent) {
814→                    Some(i) => i,
815→                    None => {
816→                        reply.error(libc::ENOENT);
817→                        return;
818→                    }
819→                };
820→                let children = parent_inode.children.clone().unwrap_or_default();
821→                let mut matches: Vec<(u64, String)> = Vec::new();
822→                for &child_ino in &children {
823→                    if let Some(child) = fs.inodes.get(child_ino) {
824→                        if is_platform_special(&child.name) {
825→                            continue;
826→                        }
827→                        if child.name.ends_with(name_str) && child.name.len() > name_str.len() {
828→                            matches.push((child_ino, child.name.clone()));
829→                        }
830→                    }
831→                }
832→                if matches.len() == 1 {
833→                    log::debug!(
834→                        "rename suffix-match: truncated {:?} matched full name {:?}",
835→                        name_str, matches[0].1
836→                    );
837→                    (matches[0].0, matches[0].1.clone())
838→                } else {
839→                    log::debug!(
840→                        "rename failed: {:?} not found (suffix matches: {})",
841→                        name_str, matches.len()
842→                    );
843→                    reply.error(libc::ENOENT);
844→                    return;
845→                }
846→            }
847→        };
848→
849→        let name_str = &actual_name;
850→
851→        log::debug!(
852→            "rename: {} (ino {}) in parent {} -> {} in parent {}",
853→            name_str, source_ino, parent, newname_str, newparent,
854→        );
855→
856→        // If destination exists, handle replacement
857→        if let Some(dest_ino) = fs.inodes.find_child(newparent, newname_str) {
858→            // Self-replace (rename "a" to "a" in same dir): no-op
859→            if dest_ino == source_ino {
860→                reply.ok();
861→                return;
862→            }
863→
864→            if let Some(dest_inode) = fs.inodes.get(dest_ino) {
865→                // Validate kind compatibility (POSIX: can't replace file with dir or vice versa)
866→                let source_is_dir = fs.inodes.get(source_ino)
867→                    .map(|i| matches!(i.kind, InodeKind::Root { .. } | InodeKind::Folder { .. }))
868→                    .unwrap_or(false);
869→                let dest_is_dir = matches!(
870→                    dest_inode.kind,
871→                    InodeKind::Root { .. } | InodeKind::Folder { .. }
872→                );
873→                if source_is_dir && !dest_is_dir {
874→                    reply.error(libc::ENOTDIR);
875→                    return;
876→                }
877→                if !source_is_dir && dest_is_dir {
878→                    reply.error(libc::EISDIR);
879→                    return;
880→                }
881→
882→                match &dest_inode.kind {
883→                    InodeKind::Folder { .. } => {
884→                        if let Some(ref children) = dest_inode.children {
885→                            if !children.is_empty() {
886→                                reply.error(libc::ENOTEMPTY);
887→                                return;
888→                            }
889→                        }
890→                    }
891→                    InodeKind::File { cid, .. } => {
892→                        if !cid.is_empty() {
893→                            let cid_clone = cid.clone();
894→                            let api = fs.api.clone();
895→                            fs.rt.spawn(async move {
896→                                let _ = crate::api::ipfs::unpin_content(
897→                                    &api, &cid_clone,
898→                                ).await;
899→                            });
900→                        }
901→                    }
902→                    _ => {}
903→                }
904→            }
905→            fs.inodes.remove(dest_ino);
906→        }
907→
908→        // Remove source from old parent's name index (NFC-normalized)
909→        {
910→            use unicode_normalization::UnicodeNormalization;
911→            let nfc_key: String = name_str.nfc().collect();
912→            fs.inodes.name_to_ino.remove(&(parent, nfc_key));
913→        }
914→
915→        // Update the source inode's name and parent
916→        if let Some(inode) = fs.inodes.get_mut(source_ino) {
917→            inode.name = newname_str.to_string();
918→            inode.parent_ino = newparent;
919→            inode.attr.ctime = SystemTime::now();
920→        }
921→
922→        // Update the name lookup index for the new location (NFC-normalized)
923→        {
924→            use unicode_normalization::UnicodeNormalization;
925→            let nfc_key: String = newname_str.nfc().collect();
926→            fs.inodes.name_to_ino.insert(
927→                (newparent, nfc_key),
928→                source_ino,
929→            );
930→        }
931→
932→        if parent != newparent {
933→            if let Some(old_parent) = fs.inodes.get_mut(parent) {
934→                if let Some(ref mut children) = old_parent.children {
935→                    children.retain(|&c| c != source_ino);
936→                }
937→                old_parent.attr.mtime = SystemTime::now();
938→                old_parent.attr.ctime = SystemTime::now();
939→            }
940→            if let Some(new_parent) = fs.inodes.get_mut(newparent) {
941→                if let Some(ref mut children) = new_parent.children {
942→                    children.push(source_ino);
943→                }
944→                new_parent.attr.mtime = SystemTime::now();
945→                new_parent.attr.ctime = SystemTime::now();
946→            }
947→
948→            if let Err(e) = fs.update_folder_metadata(parent) {
949→                log::error!("Failed to update old parent metadata after rename: {}", e);
950→            }
951→            if let Err(e) = fs.update_folder_metadata(newparent) {
952→                log::error!("Failed to update new parent metadata after rename: {}", e);
953→            }
954→        } else {
955→            if let Some(parent_inode) = fs.inodes.get_mut(parent) {
956→                parent_inode.attr.mtime = SystemTime::now();
957→                parent_inode.attr.ctime = SystemTime::now();
958→            }
959→            if let Err(e) = fs.update_folder_metadata(parent) {
960→                log::error!("Failed to update parent metadata after rename: {}", e);
961→            }
962→        }
963→
964→        reply.ok();
965→    }
966→
967→    /// Build a human-readable breadcrumb path for a folder inode.
968→    /// Walks parent_ino upward to root, concatenating names with " / ".
969→    /// Example: "My Vault / Documents / Reports"
970→    fn build_folder_path(fs: &CipherBoxFS, folder_ino: u64) -> String {
971→        let mut parts = Vec::new();
972→        let mut current = folder_ino;
973→        for _ in 0..20 { // Safety limit to prevent infinite loops
974→            match fs.inodes.get(current) {
975→                Some(inode) => {
976→                    match &inode.kind {
977→                        InodeKind::Root { .. } => {
978→                            parts.push("My Vault".to_string());
979→                            break;
980→                        }
981→                        _ => {
982→                            parts.push(inode.name.clone());
983→                            current = inode.parent_ino;
984→                        }
985→                    }
986→                }
987→                None => break,
988→            }
989→        }
990→        parts.reverse();
991→        parts.join(" / ")
992→    }
993→}
