 1→/**
 2→ * @cipherbox/crypto - ECIES Key Unwrapping (Decryption)
 3→ *
 4→ * Unwraps symmetric keys using ECIES with secp256k1.
 5→ * Uses eciesjs library which handles ECDH, HKDF, and AES-GCM internally.
 6→ */
 7→
 8→import { decrypt } from 'eciesjs';
 9→import { CryptoError } from '../types';
10→import { SECP256K1_PRIVATE_KEY_SIZE, ECIES_MIN_CIPHERTEXT_SIZE } from '../constants';
11→
12→/**
13→ * Unwrap a key using ECIES decryption.
14→ *
15→ * Decrypts a wrapped key using the recipient's private key.
16→ * Only succeeds if the key was wrapped with the corresponding public key.
17→ *
18→ * @param wrappedKey - ECIES ciphertext from wrapKey
19→ * @param privateKey - 32-byte secp256k1 private key
20→ * @returns Original unwrapped key
21→ * @throws CryptoError with generic message on any failure
22→ */
23→export async function unwrapKey(
24→  wrappedKey: Uint8Array,
25→  privateKey: Uint8Array
26→): Promise<Uint8Array> {
27→  // Validate private key size
28→  if (privateKey.length !== SECP256K1_PRIVATE_KEY_SIZE) {
29→    throw new CryptoError('Key unwrapping failed', 'INVALID_PRIVATE_KEY_SIZE');
30→  }
31→
32→  // Validate minimum ciphertext size (ephemeral pubkey + auth tag)
33→  if (wrappedKey.length < ECIES_MIN_CIPHERTEXT_SIZE) {
34→    throw new CryptoError('Key unwrapping failed', 'KEY_UNWRAPPING_FAILED');
35→  }
36→
37→  try {
38→    // eciesjs decrypt handles:
39→    // 1. Extract ephemeral public key from ciphertext
40→    // 2. ECDH key agreement with private key
41→    // 3. HKDF key derivation
42→    // 4. AES-GCM decryption with auth tag verification
43→    const unwrapped = decrypt(privateKey, wrappedKey);
44→    // Convert Buffer to Uint8Array for consistent API
45→    return new Uint8Array(unwrapped);
46→  } catch {
47→    // Generic error to prevent oracle attacks
48→    // Do NOT reveal whether:
49→    // - Private key was wrong
50→    // - Ciphertext was modified
51→    // - Auth tag failed
52→    throw new CryptoError('Key unwrapping failed', 'KEY_UNWRAPPING_FAILED');
53→  }
54→}
