  1→/**
  2→ * @cipherbox/crypto - File Metadata Encryption
  3→ *
  4→ * Encrypts and decrypts per-file metadata using AES-256-GCM.
  5→ * File metadata is encrypted with the parent folder's folderKey
  6→ * (NOT the file's own encryption key).
  7→ */
  8→
  9→import { encryptAesGcm, decryptAesGcm } from '../aes';
 10→import { generateIv, bytesToHex, hexToBytes } from '../utils';
 11→import { CryptoError } from '../types';
 12→import type { FileMetadata, EncryptedFileMetadata, VersionEntry } from './types';
 13→
 14→/**
 15→ * [SECURITY: MEDIUM-08] Chunk-based base64 encoding to avoid call stack issues
 16→ * with large Uint8Arrays (spread operator has argument limits ~65536)
 17→ */
 18→function uint8ArrayToBase64(bytes: Uint8Array): string {
 19→  const CHUNK_SIZE = 32768;
 20→  let result = '';
 21→  for (let i = 0; i < bytes.length; i += CHUNK_SIZE) {
 22→    const chunk = bytes.subarray(i, Math.min(i + CHUNK_SIZE, bytes.length));
 23→    result += String.fromCharCode(...chunk);
 24→  }
 25→  return btoa(result);
 26→}
 27→
 28→/**
 29→ * Validates a single version entry from the versions array.
 30→ * All fields are required (versions always have explicit encryption mode).
 31→ */
 32→function validateVersionEntry(entry: unknown, index: number): VersionEntry {
 33→  if (typeof entry !== 'object' || entry === null) {
 34→    throw new CryptoError(
 35→      `Invalid file metadata format: versions[${index}] is not an object`,
 36→      'DECRYPTION_FAILED'
 37→    );
 38→  }
 39→
 40→  const obj = entry as Record<string, unknown>;
 41→
 42→  if (typeof obj.cid !== 'string') {
 43→    throw new CryptoError(
 44→      `Invalid file metadata format: versions[${index}].cid must be string`,
 45→      'DECRYPTION_FAILED'
 46→    );
 47→  }
 48→  if (typeof obj.fileKeyEncrypted !== 'string') {
 49→    throw new CryptoError(
 50→      `Invalid file metadata format: versions[${index}].fileKeyEncrypted must be string`,
 51→      'DECRYPTION_FAILED'
 52→    );
 53→  }
 54→  if (typeof obj.fileIv !== 'string') {
 55→    throw new CryptoError(
 56→      `Invalid file metadata format: versions[${index}].fileIv must be string`,
 57→      'DECRYPTION_FAILED'
 58→    );
 59→  }
 60→  if (typeof obj.size !== 'number') {
 61→    throw new CryptoError(
 62→      `Invalid file metadata format: versions[${index}].size must be number`,
 63→      'DECRYPTION_FAILED'
 64→    );
 65→  }
 66→  if (typeof obj.timestamp !== 'number') {
 67→    throw new CryptoError(
 68→      `Invalid file metadata format: versions[${index}].timestamp must be number`,
 69→      'DECRYPTION_FAILED'
 70→    );
 71→  }
 72→  if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
 73→    throw new CryptoError(
 74→      `Invalid file metadata format: versions[${index}].encryptionMode must be GCM or CTR`,
 75→      'DECRYPTION_FAILED'
 76→    );
 77→  }
 78→
 79→  return {
 80→    cid: obj.cid as string,
 81→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
 82→    fileIv: obj.fileIv as string,
 83→    size: obj.size as number,
 84→    timestamp: obj.timestamp as number,
 85→    encryptionMode: obj.encryptionMode as 'GCM' | 'CTR',
 86→  };
 87→}
 88→
 89→/**
 90→ * [SECURITY: MEDIUM-07] Runtime validation for decrypted file metadata.
 91→ * Ensures the decrypted data conforms to the expected FileMetadata schema.
 92→ */
 93→export function validateFileMetadata(data: unknown): FileMetadata {
 94→  if (typeof data !== 'object' || data === null) {
 95→    throw new CryptoError('Invalid file metadata format: not an object', 'DECRYPTION_FAILED');
 96→  }
 97→
 98→  const obj = data as Record<string, unknown>;
 99→
100→  // Validate version field
101→  if (obj.version !== 'v1') {
102→    throw new CryptoError('Invalid file metadata format: unsupported version', 'DECRYPTION_FAILED');
103→  }
104→
105→  // Validate required string fields
106→  if (typeof obj.cid !== 'string') {
107→    throw new CryptoError('Invalid file metadata format: cid must be string', 'DECRYPTION_FAILED');
108→  }
109→  if (typeof obj.fileKeyEncrypted !== 'string') {
110→    throw new CryptoError(
111→      'Invalid file metadata format: fileKeyEncrypted must be string',
112→      'DECRYPTION_FAILED'
113→    );
114→  }
115→  if (typeof obj.fileIv !== 'string') {
116→    throw new CryptoError(
117→      'Invalid file metadata format: fileIv must be string',
118→      'DECRYPTION_FAILED'
119→    );
120→  }
121→  if (typeof obj.mimeType !== 'string') {
122→    throw new CryptoError(
123→      'Invalid file metadata format: mimeType must be string',
124→      'DECRYPTION_FAILED'
125→    );
126→  }
127→
128→  // Validate required number fields
129→  if (typeof obj.size !== 'number') {
130→    throw new CryptoError('Invalid file metadata format: size must be number', 'DECRYPTION_FAILED');
131→  }
132→  if (typeof obj.createdAt !== 'number') {
133→    throw new CryptoError(
134→      'Invalid file metadata format: createdAt must be number',
135→      'DECRYPTION_FAILED'
136→    );
137→  }
138→  if (typeof obj.modifiedAt !== 'number') {
139→    throw new CryptoError(
140→      'Invalid file metadata format: modifiedAt must be number',
141→      'DECRYPTION_FAILED'
142→    );
143→  }
144→
145→  // Validate optional encryptionMode: if present must be 'GCM' or 'CTR'; if absent default to 'GCM'
146→  if (obj.encryptionMode !== undefined) {
147→    if (obj.encryptionMode !== 'GCM' && obj.encryptionMode !== 'CTR') {
148→      throw new CryptoError(
149→        'Invalid file metadata format: encryptionMode must be GCM or CTR',
150→        'DECRYPTION_FAILED'
151→      );
152→    }
153→  }
154→
155→  // Validate optional versions array
156→  let validatedVersions: VersionEntry[] | undefined;
157→  if (obj.versions !== undefined) {
158→    if (!Array.isArray(obj.versions)) {
159→      throw new CryptoError(
160→        'Invalid file metadata format: versions must be an array',
161→        'DECRYPTION_FAILED'
162→      );
163→    }
164→    if (obj.versions.length > 0) {
165→      validatedVersions = obj.versions.map((entry: unknown, i: number) =>
166→        validateVersionEntry(entry, i)
167→      );
168→    }
169→  }
170→
171→  const result: FileMetadata = {
172→    version: 'v1',
173→    cid: obj.cid as string,
174→    fileKeyEncrypted: obj.fileKeyEncrypted as string,
175→    fileIv: obj.fileIv as string,
176→    size: obj.size as number,
177→    mimeType: obj.mimeType as string,
178→    encryptionMode: (obj.encryptionMode as 'GCM' | 'CTR' | undefined) ?? 'GCM',
179→    createdAt: obj.createdAt as number,
180→    modifiedAt: obj.modifiedAt as number,
181→  };
182→
183→  if (validatedVersions) {
184→    result.versions = validatedVersions;
185→  }
186→
187→  return result;
188→}
