190→/**
191→ * Encrypts file metadata with AES-256-GCM using the parent folder's key.
192→ *
193→ * @param metadata - Plaintext file metadata object
194→ * @param folderKey - 32-byte AES key of the parent folder
195→ * @returns Encrypted metadata with IV (hex) and ciphertext (base64)
196→ */
197→export async function encryptFileMetadata(
198→  metadata: FileMetadata,
199→  folderKey: Uint8Array
200→): Promise<EncryptedFileMetadata> {
201→  // Generate random IV for this encryption
202→  const iv = generateIv();
203→
204→  // Serialize metadata to JSON bytes
205→  const plaintext = new TextEncoder().encode(JSON.stringify(metadata));
206→
207→  // Encrypt with AES-256-GCM
208→  const ciphertext = await encryptAesGcm(plaintext, folderKey, iv);
209→
210→  // Encode for storage
211→  // [SECURITY: MEDIUM-08] Use chunked base64 encoding for large metadata
212→  return {
213→    iv: bytesToHex(iv),
214→    data: uint8ArrayToBase64(ciphertext),
215→  };
216→}
