 1→/**
 2→ * @cipherbox/crypto - Folder Metadata Types
 3→ *
 4→ * Type definitions for encrypted folder metadata stored in IPNS records.
 5→ * v2 schema with per-file IPNS pointers (FilePointer children).
 6→ */
 7→
 8→import type { FilePointer } from '../file/types';
 9→
10→/**
11→ * Decrypted folder metadata structure (v2).
12→ * The entire FolderMetadata object is encrypted as a single blob with AES-256-GCM.
13→ * Children are FolderEntry (subfolders) or FilePointer (slim IPNS references).
14→ */
15→export type FolderMetadata = {
16→  /** Schema version */
17→  version: 'v2';
18→  /** Folders and file pointers in this folder */
19→  children: FolderChild[];
20→};
21→
22→/**
23→ * A child entry can be either a folder or a file pointer.
24→ */
25→export type FolderChild = FolderEntry | FilePointer;
26→
27→/**
28→ * Subfolder entry within folder metadata.
29→ * Contains ECIES-wrapped keys for accessing the subfolder.
30→ */
31→export type FolderEntry = {
32→  type: 'folder';
33→  /** UUID for internal reference */
34→  id: string;
35→  /** Folder name (plaintext, since whole metadata is encrypted) */
36→  name: string;
37→  /** IPNS name for this subfolder (k51... format) */
38→  ipnsName: string;
39→  /** Hex-encoded ECIES-wrapped Ed25519 private key for IPNS signing */
40→  ipnsPrivateKeyEncrypted: string;
41→  /** Hex-encoded ECIES-wrapped AES-256 key for decrypting subfolder metadata */
42→  folderKeyEncrypted: string;
43→  /** Creation timestamp (Unix ms) */
44→  createdAt: number;
45→  /** Last modification timestamp (Unix ms) */
46→  modifiedAt: number;
47→};
48→
49→/**
50→ * Encrypted folder metadata for storage/transmission.
51→ * This is what gets uploaded to IPFS and referenced by IPNS.
52→ */
53→export type EncryptedFolderMetadata = {
54→  /** Hex-encoded 12-byte IV for AES-GCM */
55→  iv: string;
56→  /** Base64-encoded AES-GCM ciphertext (includes 16-byte auth tag) */
57→  data: string;
58→};
