126→// ---------------------------------------------------------------------------
127→// Public API: initializeBin
128→// ---------------------------------------------------------------------------
129→
130→/**
131→ * Initialize or load the recycle bin on login.
132→ *
133→ * Derives the deterministic IPNS keypair, resolves existing bin metadata
134→ * from IPNS (or creates empty state), and populates the bin store.
135→ *
136→ * Non-blocking: errors are logged, not thrown.
137→ */
138→export async function initializeBin(params: {
139→  userPrivateKey: Uint8Array;
140→  userPublicKey: Uint8Array;
141→}): Promise<void> {
142→  const store = useBinStore.getState();
143→  store.setLoading(true);
144→
145→  try {
146→    // Reset TEE enrollment tracking for new session
147→    binTeeEnrolled = false;
148→
149→    // Try to load existing bin metadata (derives IPNS keypair internally)
150→    const loaded = await loadBinMetadata({ userPrivateKey: params.userPrivateKey });
151→
152→    // Set IPNS name from loaded result, or derive if no bin exists yet
153→    if (loaded) {
154→      store.setBinIpnsName(loaded.ipnsName);
155→    } else {
156→      const binIpns = await deriveBinIpnsKeypair(params.userPrivateKey);
157→      store.setBinIpnsName(binIpns.ipnsName);
158→    }
159→
160→    if (loaded) {
161→      store.setEntries(loaded.metadata.entries, loaded.metadata.sequenceNumber);
162→    } else {
163→      // No bin exists yet -- initialize with empty state
164→      store.setEntries([], 0);
165→    }
166→  } catch (error) {
167→    console.error('[Bin] Failed to initialize bin:', error);
168→    store.setError(error instanceof Error ? error.message : 'Failed to initialize bin');
169→    store.setLoading(false);
170→  }
171→}
