251→  if (items.length === 0) return;
252→
253→  const now = Date.now();
254→  const newEntries: BinEntry[] = items.map((item) => {
255→    const isFile = item.type === 'file';
256→    return {
257→      id: crypto.randomUUID(),
258→      itemType: isFile ? 'file' : 'folder',
259→      name: item.name,
260→      originalParentIpnsName: parentIpnsName,
261→      originalPath: parentPath,
262→      deletedAt: now,
263→      size: 0,
264→      mimeType: '',
265→      filePointer: isFile ? (item as FilePointer) : undefined,
