267→    };
268→  });
269→
270→  const store = useBinStore.getState();
271→  const currentEntries = [...store.entries, ...newEntries];
272→  const newSeq = store.sequenceNumber + 1;
273→
274→  const metadata: RecycleBinMetadata = {
275→    version: BIN_METADATA_VERSION,
276→    sequenceNumber: newSeq,
277→    entries: currentEntries,
278→  };
279→
280→  // Non-blocking: folder delete already committed, bin is best-effort
281→  try {
282→    await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
