297→ * FolderChild. Handles name collisions (appends " (restored)"). If original
298→ * parent is also in the bin, attempts recursive parent restore (max depth 5).
299→ * Falls back to root folder if parent is gone.
300→ */
301→export async function restoreFromBin(params: {
302→  entryId: string;
303→  userPublicKey: Uint8Array;
304→  userPrivateKey: Uint8Array;
305→}): Promise<void> {
306→  return restoreFromBinInternal(params, 0);
