309→async function restoreFromBinInternal(
310→  params: { entryId: string; userPublicKey: Uint8Array; userPrivateKey: Uint8Array },
311→  depth: number
312→): Promise<void> {
313→  const { entryId, userPublicKey, userPrivateKey } = params;
314→
315→  const binStore = useBinStore.getState();
316→  const entry = binStore.entries.find((e) => e.id === entryId);
317→  if (!entry) throw new Error('Bin entry not found');
318→
319→  // Resolve original parent folder
320→  const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, depth, {
321→    userPublicKey,
322→    userPrivateKey,
323→  });
324→
325→  // Get the FolderChild to restore
326→  const child = getRestoredChild(entry);
327→
328→  // Check for name collisions in target folder and rename if needed
329→  const finalChild = resolveNameCollision(child, targetFolder.children);
330→
331→  // Add child back to target folder
332→  const { updateFolderMetadata } = await import('./folder.service');
333→  const updatedChildren = [...targetFolder.children, finalChild];
334→  const { newSequenceNumber } = await updateFolderMetadata({
335→    folderId: targetFolder.id,
336→    children: updatedChildren,
337→    folderKey: targetFolder.folderKey,
338→    ipnsPrivateKey: targetFolder.ipnsPrivateKey,
339→    ipnsName: targetFolder.ipnsName,
340→    sequenceNumber: targetFolder.sequenceNumber,
341→  });
342→
343→  // Update folder store
344→  const folderStore = useFolderStore.getState();
345→  folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
346→  folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
347→
348→  // If restoring a folder, re-add the folder node to the store
349→  if (entry.itemType === 'folder' && entry.folderEntry) {
350→    const existingNode = folderStore.folders[entry.folderEntry.id];
351→    if (!existingNode) {
352→      // Create a placeholder node -- it will be fully loaded on next navigation
353→      folderStore.setFolder({
354→        id: entry.folderEntry.id,
355→        name: finalChild.name,
356→        ipnsName: entry.folderEntry.ipnsName,
357→        parentId: targetFolder.id,
358→        children: [],
359→        isLoaded: false,
360→        isLoading: false,
361→        sequenceNumber: 0n,
362→        // These will be populated when the folder is loaded
363→        folderKey: new Uint8Array(32),
364→        ipnsPrivateKey: new Uint8Array(64),
365→      });
366→    }
367→  }
368→
369→  // Remove entry from bin metadata and publish
370→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
371→}
372→
373→// ---------------------------------------------------------------------------
374→// Public API: restoreFromBinBatch
375→// ---------------------------------------------------------------------------
376→
377→/**
378→ * Restore multiple bin entries, publishing to the bin IPNS only once at the end.
379→ *
380→ * Each item is restored to its target folder (which may each require a folder
381→ * publish), but the bin metadata is updated in a single publish.
382→ */
383→export async function restoreFromBinBatch(params: {
384→  entryIds: string[];
385→  userPublicKey: Uint8Array;
386→  userPrivateKey: Uint8Array;
387→}): Promise<void> {
388→  const { entryIds, userPublicKey, userPrivateKey } = params;
389→  if (entryIds.length === 0) return;
390→
391→  const { updateFolderMetadata } = await import('./folder.service');
392→
393→  const restoredIds: string[] = [];
394→
395→  for (const entryId of entryIds) {
396→    // Read fresh state each iteration — recursive restores may mutate the store
397→    const entry = useBinStore.getState().entries.find((e) => e.id === entryId);
398→    if (!entry) continue;
399→
400→    try {
401→      const targetFolder = await resolveTargetFolder(entry.originalParentIpnsName, 0, {
402→        userPublicKey,
403→        userPrivateKey,
404→      });
405→
406→      const child = getRestoredChild(entry);
407→      const finalChild = resolveNameCollision(child, targetFolder.children);
408→
409→      const updatedChildren = [...targetFolder.children, finalChild];
410→      const { newSequenceNumber } = await updateFolderMetadata({
411→        folderId: targetFolder.id,
412→        children: updatedChildren,
413→        folderKey: targetFolder.folderKey,
414→        ipnsPrivateKey: targetFolder.ipnsPrivateKey,
415→        ipnsName: targetFolder.ipnsName,
416→        sequenceNumber: targetFolder.sequenceNumber,
417→      });
418→
419→      const folderStore = useFolderStore.getState();
420→      folderStore.updateFolderChildren(targetFolder.id, updatedChildren);
421→      folderStore.updateFolderSequence(targetFolder.id, newSequenceNumber);
422→
423→      if (entry.itemType === 'folder' && entry.folderEntry) {
424→        const existingNode = folderStore.folders[entry.folderEntry.id];
425→        if (!existingNode) {
426→          folderStore.setFolder({
427→            id: entry.folderEntry.id,
428→            name: finalChild.name,
429→            ipnsName: entry.folderEntry.ipnsName,
430→            parentId: targetFolder.id,
431→            children: [],
432→            isLoaded: false,
433→            isLoading: false,
434→            sequenceNumber: 0n,
435→            folderKey: new Uint8Array(32),
436→            ipnsPrivateKey: new Uint8Array(64),
437→          });
438→        }
439→      }
440→
441→      restoredIds.push(entryId);
442→    } catch (err) {
443→      console.error(`[Bin] Failed to restore entry ${entry.id}:`, err);
444→    }
445→  }
446→
447→  // Single bin IPNS publish for all restored entries
448→  if (restoredIds.length > 0) {
449→    await removeEntriesFromBin(restoredIds, { userPublicKey, userPrivateKey });
450→  }
451→}
452→
453→// ---------------------------------------------------------------------------
454→// Public API: permanentlyDelete
455→// ---------------------------------------------------------------------------
456→
457→/**
458→ * Permanently delete a bin entry: unpin CIDs and update quota.
459→ *
460→ * For files: resolves file IPNS -> gets CID -> unpins.
461→ * For folders: recursively resolves all descendant file CIDs -> unpins all.
462→ */
463→export async function permanentlyDelete(params: {
464→  entryId: string;
465→  userPublicKey: Uint8Array;
466→  userPrivateKey: Uint8Array;
467→}): Promise<void> {
468→  const { entryId, userPublicKey, userPrivateKey } = params;
469→
470→  const binStore = useBinStore.getState();
471→  const entry = binStore.entries.find((e) => e.id === entryId);
472→  if (!entry) throw new Error('Bin entry not found');
473→
474→  // Perform CID cleanup
475→  await cleanupEntryCids(entry);
476→
477→  // Remove from bin metadata and publish
478→  await removeEntriesFromBin([entryId], { userPublicKey, userPrivateKey });
479→}
480→
481→// ---------------------------------------------------------------------------
482→// Public API: permanentlyDeleteBatch
483→// ---------------------------------------------------------------------------
484→
485→/**
486→ * Permanently delete multiple bin entries in a single IPNS publish.
487→ *
488→ * Cleans up CIDs for all entries (best-effort), then publishes once.
489→ */
490→export async function permanentlyDeleteBatch(params: {
491→  entryIds: string[];
492→  userPublicKey: Uint8Array;
493→  userPrivateKey: Uint8Array;
494→}): Promise<void> {
495→  const { entryIds, userPublicKey, userPrivateKey } = params;
496→  if (entryIds.length === 0) return;
497→
498→  const binStore = useBinStore.getState();
499→  const idsSet = new Set(entryIds);
500→  const entriesToDelete = binStore.entries.filter((e) => idsSet.has(e.id));
501→
502→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
503→  for (const entry of entriesToDelete) {
504→    try {
505→      await cleanupEntryCids(entry);
506→    } catch (err) {
507→      console.error(`[Bin] CID cleanup failed for entry ${entry.id}:`, err);
508→    }
509→  }
510→
511→  // Remove all from bin metadata in a single publish
512→  await removeEntriesFromBin(entryIds, { userPublicKey, userPrivateKey });
513→}
514→
515→// ---------------------------------------------------------------------------
516→// Public API: emptyBin
517→// ---------------------------------------------------------------------------
518→
519→/**
520→ * Permanently delete all bin entries.
521→ *
522→ * Processes each entry's CID cleanup, then publishes empty bin metadata.
523→ */
524→export async function emptyBin(params: {
525→  userPublicKey: Uint8Array;
526→  userPrivateKey: Uint8Array;
527→}): Promise<void> {
528→  const { userPublicKey, userPrivateKey } = params;
529→
530→  const binStore = useBinStore.getState();
531→  const entries = [...binStore.entries];
532→
533→  // Cleanup CIDs for all entries (best-effort, continue on individual failures)
534→  for (const entry of entries) {
535→    try {
536→      await cleanupEntryCids(entry);
537→    } catch (err) {
538→      console.error(`[Bin] Failed to cleanup CIDs for entry ${entry.id}:`, err);
539→    }
540→  }
541→
542→  // Publish empty bin metadata
543→  const newSeq = binStore.sequenceNumber + 1;
544→  const metadata: RecycleBinMetadata = {
545→    version: BIN_METADATA_VERSION,
546→    sequenceNumber: newSeq,
547→    entries: [],
548→  };
549→
550→  await saveBinMetadata({ metadata, userPublicKey, userPrivateKey });
551→
552→  // Update local store
553→  binStore.setEntries([], newSeq);
554→}
555→
556→// ---------------------------------------------------------------------------
557→// Public API: purgeExpired
558→// ---------------------------------------------------------------------------
559→
560→/**
561→ * Purge expired bin entries based on retention period.
562→ *
563→ * Filters entries past their retention, cleans up CIDs, and publishes
564→ * updated bin metadata in a single IPNS publish.
565→ */
566→export async function purgeExpired(params: {
567→  retentionDays: number;
568→  userPublicKey: Uint8Array;
569→  userPrivateKey: Uint8Array;
570→}): Promise<void> {
571→  const { retentionDays, userPublicKey, userPrivateKey } = params;
572→
573→  const binStore = useBinStore.getState();
574→  const retentionMs = retentionDays * 24 * 60 * 60 * 1000;
575→  const now = Date.now();
576→
577→  const expired = binStore.entries.filter((e) => now - e.deletedAt > retentionMs);
578→  if (expired.length === 0) return;
579→
580→  console.log(`[Bin] Purging ${expired.length} expired entries`);
581→
582→  // Cleanup CIDs for expired entries (best-effort)
583→  for (const entry of expired) {
584→    try {
585→      await cleanupEntryCids(entry);
586→    } catch (err) {
587→      console.error(`[Bin] Failed to cleanup CIDs for expired entry ${entry.id}:`, err);
588→    }
589→  }
590→
591→  // Remove expired entries and publish
592→  const expiredIds = expired.map((e) => e.id);
593→  await removeEntriesFromBin(expiredIds, { userPublicKey, userPrivateKey });
594→}
595→
596→// ---------------------------------------------------------------------------
597→// Internal helpers
598→// ---------------------------------------------------------------------------
599→
600→/**
601→ * Remove entries from bin metadata and publish the updated metadata.
602→ */
603→async function removeEntriesFromBin(
604→  entryIds: string[],
605→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
606→): Promise<void> {
607→  const binStore = useBinStore.getState();
608→  const idsToRemove = new Set(entryIds);
609→  const remainingEntries = binStore.entries.filter((e) => !idsToRemove.has(e.id));
610→  const newSeq = binStore.sequenceNumber + 1;
611→
612→  const metadata: RecycleBinMetadata = {
613→    version: BIN_METADATA_VERSION,
614→    sequenceNumber: newSeq,
615→    entries: remainingEntries,
616→  };
617→
618→  await saveBinMetadata({
619→    metadata,
620→    userPublicKey: params.userPublicKey,
621→    userPrivateKey: params.userPrivateKey,
622→  });
623→
624→  // Update local store (use setEntries with explicit seq to avoid double-increment)
625→  binStore.setEntries(remainingEntries, newSeq);
626→}
627→
628→/**
629→ * Cleanup CIDs for a bin entry (unpin from IPFS + update quota).
630→ *
631→ * Files: resolve file IPNS -> get CID -> unpin
632→ * Folders: recursively resolve descendant file CIDs -> unpin all
633→ */
634→async function cleanupEntryCids(entry: BinEntry): Promise<void> {
635→  if (entry.itemType === 'file' && entry.filePointer) {
636→    const fileIpnsName = entry.filePointer.fileMetaIpnsName;
637→    if (fileIpnsName) {
638→      await unpinFileCids(fileIpnsName, `file ${entry.id}`);
639→    }
640→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
641→    await cleanupFolderCids(entry.folderEntry.ipnsName);
642→  }
643→}
644→
645→/**
646→ * Unpin a single file's content and metadata CIDs, and update quota.
647→ */
648→async function unpinFileCids(fileMetaIpnsName: string, label: string): Promise<void> {
649→  try {
650→    const resolved = await resolveIpnsRecord(fileMetaIpnsName);
651→    if (!resolved?.cid) return;
652→
653→    const metaBytes = await fetchFromIpfs(resolved.cid);
654→    const metaJson = new TextDecoder().decode(metaBytes);
655→    const fileMeta = JSON.parse(metaJson);
656→
657→    if (fileMeta.cid) {
658→      await unpinFromIpfs(fileMeta.cid);
659→      if (fileMeta.size && typeof fileMeta.size === 'number') {
660→        useQuotaStore.getState().removeUsage(fileMeta.size);
661→      }
662→    }
663→
664→    await unpinFromIpfs(resolved.cid).catch(() => {});
665→  } catch (err) {
666→    console.error(`[Bin] CID cleanup failed for ${label}:`, err);
667→  }
668→}
669→
670→/**
671→ * Recursively unpin all CIDs in a folder tree.
672→ */
673→async function cleanupFolderCids(folderIpnsName: string): Promise<void> {
674→  try {
675→    const resolved = await resolveIpnsRecord(folderIpnsName);
676→    if (!resolved?.cid) return;
677→
678→    // We don't have the folder key here, so we check if the folder is
679→    // loaded in the store first
680→    const folders = useFolderStore.getState().folders;
681→    const folderNode = Object.values(folders).find((f) => f.ipnsName === folderIpnsName);
682→
683→    if (folderNode) {
684→      for (const child of folderNode.children) {
685→        if (child.type === 'file') {
686→          const fp = child as FilePointer;
687→          if (fp.fileMetaIpnsName) {
688→            await unpinFileCids(fp.fileMetaIpnsName, 'nested file');
689→          }
690→        } else if (child.type === 'folder') {
691→          const fe = child as FolderEntry;
692→          await cleanupFolderCids(fe.ipnsName);
693→        }
694→      }
695→    }
696→
697→    await unpinFromIpfs(resolved.cid).catch(() => {});
698→  } catch (err) {
699→    console.error(`[Bin] Folder CID cleanup failed for ${folderIpnsName}:`, err);
700→  }
701→}
702→
703→/**
704→ * Resolve the target folder for a restore operation.
705→ *
706→ * Walks the folder store to find a folder with the given IPNS name.
707→ * If not found, checks if the parent is in the bin (recursive restore).
708→ * Falls back to root folder.
709→ */
710→async function resolveTargetFolder(
711→  parentIpnsName: string,
712→  depth: number,
713→  params: { userPublicKey: Uint8Array; userPrivateKey: Uint8Array }
714→): Promise<FolderNode> {
715→  // Max recursion depth to prevent infinite loops
716→  if (depth > 5) {
717→    console.warn('[Bin] Max restore depth reached, falling back to root');
718→    return getRootFolder();
719→  }
720→
721→  // Look up folder by IPNS name in folder store
722→  const folders = useFolderStore.getState().folders;
723→  const targetFolder = Object.values(folders).find((f) => f.ipnsName === parentIpnsName);
724→
725→  if (targetFolder) {
726→    return targetFolder;
727→  }
728→
729→  // Check if parent is in the bin
730→  const binStore = useBinStore.getState();
731→  const parentBinEntry = binStore.entries.find(
732→    (e) => e.itemType === 'folder' && e.folderEntry && e.folderEntry.ipnsName === parentIpnsName
733→  );
734→
735→  if (parentBinEntry) {
736→    // Restore parent first (recursive, depth incremented)
737→    console.log(`[Bin] Restoring parent folder (id: ${parentBinEntry.id}) first`);
738→    await restoreFromBinInternal(
739→      {
740→        entryId: parentBinEntry.id,
741→        userPublicKey: params.userPublicKey,
742→        userPrivateKey: params.userPrivateKey,
743→      },
744→      depth + 1
745→    );
746→
747→    // After restoring parent, try to find it again
748→    const updatedFolders = useFolderStore.getState().folders;
749→    const restoredParent = Object.values(updatedFolders).find((f) => f.ipnsName === parentIpnsName);
750→    if (restoredParent) {
751→      return restoredParent;
752→    }
753→  }
754→
755→  // Parent truly gone -- restore to root
756→  console.warn(`[Bin] Original parent not found (${parentIpnsName}), restoring to root`);
757→  return getRootFolder();
758→}
759→
760→/**
761→ * Get the root folder from the folder store.
762→ */
763→function getRootFolder(): FolderNode {
764→  const folders = useFolderStore.getState().folders;
765→  const root = folders['root'];
766→  if (root) return root;
767→
768→  // Fallback: construct from vault store
769→  const vault = useVaultStore.getState();
770→  if (!vault.rootFolderKey || !vault.rootIpnsKeypair || !vault.rootIpnsName) {
771→    throw new Error('Vault not initialized - cannot restore to root');
772→  }
773→
774→  return {
775→    id: 'root',
776→    name: 'My Vault',
777→    ipnsName: vault.rootIpnsName,
778→    parentId: null,
779→    children: folders['root']?.children ?? [],
780→    isLoaded: true,
781→    isLoading: false,
782→    sequenceNumber: 0n,
783→    folderKey: vault.rootFolderKey,
784→    ipnsPrivateKey: vault.rootIpnsKeypair.privateKey,
785→  };
786→}
787→
788→/**
789→ * Get the FolderChild to restore from a bin entry.
790→ */
791→function getRestoredChild(entry: BinEntry): FolderChild {
792→  if (entry.itemType === 'file' && entry.filePointer) {
793→    return { ...entry.filePointer, modifiedAt: Date.now() };
794→  } else if (entry.itemType === 'folder' && entry.folderEntry) {
795→    return { ...entry.folderEntry, modifiedAt: Date.now() };
796→  }
797→  throw new Error(`Bin entry ${entry.id} has no stored item reference`);
798→}
799→
800→/**
801→ * Check for name collisions and rename if needed.
802→ */
803→function resolveNameCollision(child: FolderChild, existingChildren: FolderChild[]): FolderChild {
804→  const existingNames = new Set(existingChildren.map((c) => c.name));
805→  if (!existingNames.has(child.name)) {
806→    return child;
807→  }
808→
809→  // Append " (restored)" suffix, incrementing if needed
810→  let newName = `${child.name} (restored)`;
811→  let counter = 2;
812→  while (existingNames.has(newName)) {
813→    newName = `${child.name} (restored ${counter})`;
814→    counter++;
815→  }
816→
817→  return { ...child, name: newName };
818→}
